CREATE OR REPLACE FUNCTION openpc.guard_participant_lifecycle_history()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-HISTORY-IMMUTABLE';
END $$;
DROP TRIGGER IF EXISTS participant_lifecycle_history ON control.participant_lifecycle_transition;
CREATE TRIGGER participant_lifecycle_history BEFORE UPDATE OR DELETE ON control.participant_lifecycle_transition
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_participant_lifecycle_history();

CREATE OR REPLACE FUNCTION openpc.require_participant_lifecycle_history()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE mode text:=current_setting('openpc.context_mode');
 owner uuid:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 privacy uuid:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 op uuid:=current_setting('openpc.operation_id')::uuid;
 action text:=current_setting('openpc.action_intent_id'); valid boolean;
BEGIN
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,NEW.privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.participant p JOIN control.outbox_event event ON event.participant_id=p.participant_id
   AND event.event_id=NEW.operation_id AND event.event_type='openpc.identity.participant.epoch.advanced.v1'
   WHERE p.participant_id=NEW.participant_id AND p.authority_epoch=NEW.new_epoch AND p.row_version=NEW.revision
    AND p.root_privacy_domain_id=NEW.privacy_domain_id
    AND (p.archived_at IS NOT NULL)=(NEW.mutation='ARCHIVE')) INTO valid;
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-EFFECT'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.source_participant_id,NEW.source_privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate candidate JOIN control.mutation_evidence evidence
   ON evidence.participant_id=candidate.participant_id AND evidence.operation_id=candidate.consumed_operation_id
    AND evidence.candidate_digest=candidate.candidate_digest AND evidence.catalog_operation_id=candidate.catalog_operation_id
   JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id
    AND receipt.operation_id=NEW.operation_id AND receipt.terminal_state='COMMITTED'
   WHERE candidate.participant_id=NEW.source_participant_id AND candidate.privacy_domain_id=NEW.source_privacy_domain_id
    AND candidate.state='CONSUMED' AND candidate.consumed_operation_id=NEW.operation_id
    AND candidate.catalog_operation_id='ID-OP-PARTICIPANT-'||NEW.mutation AND candidate.resource_id=NEW.participant_id
    AND candidate.candidate_document->>'privacyDomainId'=NEW.privacy_domain_id::text
    AND candidate.candidate_document->>'expectedEpoch'=NEW.prior_epoch::text
    AND candidate.expected_revision=NEW.revision-1 AND receipt.result_payload#>>'{result,epoch}'=NEW.new_epoch::text)
 INTO valid;
 PERFORM openpc.set_request_context(mode,owner,privacy,op,action,privacy IS NOT NULL);
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-PROVENANCE'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS participant_lifecycle_history_provenance ON control.participant_lifecycle_transition;
CREATE CONSTRAINT TRIGGER participant_lifecycle_history_provenance AFTER INSERT ON control.participant_lifecycle_transition
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_participant_lifecycle_history();

CREATE OR REPLACE FUNCTION openpc.require_participant_lifecycle_transition()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE transition control.participant_lifecycle_transition%ROWTYPE;
 mode text; owner uuid; privacy uuid; op uuid; action text;
 valid boolean;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-HISTORY-RETAINED'; END IF;
 IF NEW.archived_at IS NOT DISTINCT FROM OLD.archived_at THEN RETURN NULL; END IF;
 mode:=current_setting('openpc.context_mode');
 owner:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 privacy:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 op:=current_setting('openpc.operation_id')::uuid;
 action:=current_setting('openpc.action_intent_id');
 IF NOT ((OLD.state='ACTIVE' AND NEW.state='SUSPENDED' AND OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL)
      OR (OLD.state='SUSPENDED' AND NEW.state='ACTIVE' AND OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL))
    OR NEW.authority_epoch<>OLD.authority_epoch+1 OR NEW.row_version<>OLD.row_version+1 THEN
  RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-TRANSITION';
 END IF;
 PERFORM openpc.set_request_context('PLATFORM',NEW.participant_id,null,op,action,false);
 SELECT * INTO transition FROM control.participant_lifecycle_transition
  WHERE participant_id=NEW.participant_id AND new_epoch=NEW.authority_epoch AND prior_epoch=OLD.authority_epoch
   AND revision=NEW.row_version AND mutation=CASE WHEN NEW.archived_at IS NULL THEN 'RESTORE' ELSE 'ARCHIVE' END;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-HISTORY'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',transition.source_participant_id,transition.source_privacy_domain_id,op,action,true);
 SELECT EXISTS(
  SELECT 1 FROM control.mutation_candidate candidate
  JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id
   AND evidence.operation_id=candidate.consumed_operation_id AND evidence.candidate_digest=candidate.candidate_digest
   AND evidence.catalog_operation_id=candidate.catalog_operation_id AND evidence.principal_id<>evidence.checker_principal_id
  JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id
   AND receipt.operation_id=candidate.consumed_operation_id AND receipt.terminal_state='COMMITTED'
  WHERE candidate.participant_id=transition.source_participant_id AND candidate.privacy_domain_id=transition.source_privacy_domain_id
   AND candidate.consumed_operation_id=transition.operation_id AND candidate.state='CONSUMED'
   AND candidate.catalog_operation_id='ID-OP-PARTICIPANT-'||transition.mutation
   AND candidate.resource_id=NEW.participant_id AND candidate.candidate_document->>'participantId'=NEW.participant_id::text
   AND candidate.candidate_document->>'expectedEpoch'=OLD.authority_epoch::text
   AND candidate.expected_revision=OLD.row_version
   AND receipt.result_payload#>>'{result,epoch}'=NEW.authority_epoch::text
 ) INTO valid;
 PERFORM openpc.set_request_context(mode,owner,privacy,op,action,privacy IS NOT NULL);
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-PROVENANCE'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS participant_lifecycle_transition ON control.participant;
CREATE CONSTRAINT TRIGGER participant_lifecycle_transition AFTER UPDATE OR DELETE ON control.participant
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_participant_lifecycle_transition();


-- Root custody is a transaction fence, not permission to update the root.
-- Keep application UPDATE rights absent; the owner retains the lock under RLS.
CREATE OR REPLACE FUNCTION openpc.lock_platform_scope_context(p_root_id uuid)
RETURNS SETOF control.platform_context
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 PERFORM openpc.assert_request_context(false);
 RETURN QUERY SELECT p.* FROM control.platform_context p
 WHERE p.platform_context_id=p_root_id AND p.state='ACTIVE'
 AND EXISTS(SELECT 1 FROM control.authority_envelope e
   WHERE e.platform_context_id=p.platform_context_id
     AND e.participant_id=openpc.current_participant_id())
 FOR SHARE OF p;
END $$;
REVOKE ALL ON FUNCTION openpc.lock_platform_scope_context(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.guard_platform_context()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT'; END IF;
 IF NEW.platform_context_id<>OLD.platform_context_id OR NEW.owner_participant_id<>OLD.owner_participant_id
   OR NEW.created_at<>OLD.created_at OR OLD.state='RETIRED'
   OR NEW.authority_epoch<>OLD.authority_epoch+1 OR NEW.row_version<>OLD.row_version+1
   OR NEW.updated_at<=OLD.updated_at THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_context_monotonic ON control.platform_context;
CREATE TRIGGER platform_context_monotonic BEFORE UPDATE OR DELETE ON control.platform_context
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_context();

CREATE OR REPLACE FUNCTION openpc.guard_envelope_platform_binding()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
BEGIN
 IF NEW.platform_context_id IS DISTINCT FROM OLD.platform_context_id
   OR NEW.platform_authority_epoch IS DISTINCT FROM OLD.platform_authority_epoch THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS authority_envelope_platform_immutable ON control.authority_envelope;
CREATE TRIGGER authority_envelope_platform_immutable BEFORE UPDATE ON control.authority_envelope
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_envelope_platform_binding();

DROP POLICY IF EXISTS envelope_platform_custody_read ON control.authority_envelope;
CREATE POLICY envelope_platform_custody_read ON control.authority_envelope FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id));
DROP POLICY IF EXISTS platform_context_custody_lock ON control.platform_context;
CREATE POLICY platform_context_custody_lock ON control.platform_context FOR UPDATE TO openpc_control_owner
 USING(exists(select 1 from control.authority_envelope envelope
   where envelope.platform_context_id=platform_context.platform_context_id
     and openpc.matches_participant(envelope.participant_id))) WITH CHECK(false);

-- This returns custody, not permission. Callers must first verify and retain
-- their selected current envelope/grant path under the Participant fence.
CREATE OR REPLACE FUNCTION openpc.lock_authority_envelope_platform_context(p_envelope_id uuid)
RETURNS TABLE(platform_context_id uuid,platform_authority_epoch text,delegation_epoch text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control AS $$
BEGIN
 PERFORM openpc.assert_request_context(false);
 RETURN QUERY SELECT platform.platform_context_id,platform.authority_epoch::text,envelope.delegation_epoch::text
 FROM control.authority_envelope envelope JOIN control.platform_context platform
   ON platform.platform_context_id=envelope.platform_context_id
 WHERE envelope.participant_id=openpc.current_participant_id()
   AND envelope.authority_envelope_id=p_envelope_id AND envelope.state='ACTIVE'
   AND envelope.valid_from<=clock_timestamp() AND (envelope.valid_until IS NULL OR envelope.valid_until>clock_timestamp())
   AND platform.state='ACTIVE' AND platform.authority_epoch=envelope.platform_authority_epoch
 FOR SHARE OF platform;
END $$;


CREATE OR REPLACE FUNCTION openpc.identity_envelope_scope_valid(p_bytes bytea)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE scope jsonb; module jsonb; items jsonb; item jsonb; previous bytea; current_bytes bytea;
 dimension integer; module_id integer; value text;
BEGIN
 scope:=openpc.business_cbor(p_bytes);
 IF jsonb_typeof(scope) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(scope) key) IS DISTINCT FROM ARRAY['1','2','3','4','5','6','7'] THEN RETURN false; END IF;
 FOR dimension IN 3..7 LOOP
  IF jsonb_typeof(scope->dimension::text)<>'number' OR (scope->>dimension::text)!~'^(0|[1-9][0-9]{0,19})$' THEN RETURN false; END IF;
 END LOOP;
 IF (scope->>'3')::numeric>18446744073709551615 OR (scope->>'4')::numeric>18446744073709551615
   OR (scope->>'4')::numeric<=(scope->>'3')::numeric OR mod((scope->>'3')::numeric,1000)<>0
   OR mod((scope->>'4')::numeric,1000)<>0 OR (scope->>'5')::numeric NOT IN(0,1)
   OR (scope->>'6')::numeric NOT IN(0,1) OR (scope->>'7')::numeric>32 THEN RETURN false; END IF;
 FOR module_id IN 1..2 LOOP
  module:=scope->module_id::text;
  IF jsonb_typeof(module) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(module) key) IS DISTINCT FROM ARRAY['1','2','3','4','5','6','7'] THEN RETURN false; END IF;
  FOR dimension IN 1..7 LOOP
   items:=module->dimension::text; previous:=NULL;
   IF jsonb_typeof(items)<>'array' OR jsonb_array_length(items)>256 THEN RETURN false; END IF;
   FOR item IN SELECT v FROM jsonb_array_elements(items) v LOOP
    IF dimension IN(1,2) THEN
     IF jsonb_typeof(item)<>'object' OR jsonb_typeof(item->'bytes') IS DISTINCT FROM 'string' OR item<>jsonb_build_object('bytes',item->>'bytes')
       OR (item->>'bytes')!~'^[0-9a-f]{12}[1-8][0-9a-f]{3}[89ab][0-9a-f]{15}$' THEN RETURN false; END IF;
     current_bytes:=decode(item->>'bytes','hex');
    ELSE
     IF jsonb_typeof(item)<>'string' THEN RETURN false; END IF;
     value:=item#>>'{}'; current_bytes:=convert_to(value,'UTF8');
     IF octet_length(current_bytes) NOT BETWEEN 1 AND 160 OR value!~'^[A-Za-z0-9][A-Za-z0-9:._/-]*$' THEN RETURN false; END IF;
     IF dimension=6 AND value NOT IN('BREAK_GLASS','HIGH','LOW','STANDARD') THEN RETURN false; END IF;
     IF dimension=7 AND module_id=1 AND value!~'^ACT-[A-Z][A-Z0-9_]*-V[1-9][0-9]*$' THEN RETURN false; END IF;
     IF dimension=7 AND module_id=2 AND value NOT IN('CALL_RESULT_DISCLOSURE','GAS_ESTIMATE_DISCLOSURE','ACCESS_LIST_DISCLOSURE',
       'UNSIGNED_TRANSACTION_PREPARATION','SIGNED_TRANSACTION_SUBMISSION','OPERATION_STATUS_DISCLOSURE','MULTI_CALL_SIMULATION_DISCLOSURE') THEN RETURN false; END IF;
    END IF;
    IF previous IS NOT NULL AND current_bytes<=previous THEN RETURN false; END IF;
    previous:=current_bytes;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_platform_envelope_scope()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-IMMUTABLE-PLATFORM-SCOPE'; END IF;
 IF current_user<>'openpc_control_owner' OR NOT pg_has_role(session_user,'openpc_control_owner','MEMBER')
   OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
   OR NEW.installed_by<>session_user THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-AUTHORITY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.owner_participant_id) OR NOT openpc.matches_privacy(NEW.installation_privacy_domain_id)
   OR NEW.platform_authority_epoch<>1 OR NEW.admission_version<>1 OR NOT openpc.identity_envelope_scope_valid(NEW.scope_cbor)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-BINDING'; END IF;
 -- Configuration's installation owner creates this source before this adapter;
 -- the Identity migration may be installed before that cross-lane table exists.
 PERFORM 1 FROM control.participant WHERE participant_id=NEW.owner_participant_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PARTICIPANT'; END IF;
 PERFORM 1 FROM control.privacy_domain WHERE participant_id=NEW.owner_participant_id
  AND privacy_domain_id=NEW.installation_privacy_domain_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PRIVACY'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('operations-generation:'||NEW.environment_id,0))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-BUSY'; END IF;
 PERFORM 1 FROM control.operations_installation i
  WHERE i.participant_id=NEW.owner_participant_id AND i.privacy_domain_id=NEW.installation_privacy_domain_id
    AND i.environment_id=NEW.environment_id AND i.state='ACTIVE' AND i.installation_digest=NEW.installation_digest
    AND openpc.operations_source_authentication_valid(i.installation)
    AND NOT EXISTS(SELECT 1 FROM control.operations_generation_commit c WHERE c.environment_id=i.environment_id)
  FOR SHARE OF i;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PROVENANCE'; END IF;
 PERFORM 1 FROM control.platform_context p WHERE p.platform_context_id=NEW.platform_context_id
   AND p.owner_participant_id=NEW.owner_participant_id AND p.authority_epoch=NEW.platform_authority_epoch AND p.state='ACTIVE'
   AND p.row_version=1 AND p.xmin=(mod(pg_current_xact_id()::text::numeric,4294967296))::text::xid FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INITIAL-ROOT'; END IF;
 expected:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
  openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
  openpc.business_uuid(NEW.platform_context_id),openpc.business_uuid(NEW.owner_participant_id),
  openpc.business_uuid(NEW.installation_privacy_domain_id),NEW.platform_authority_epoch,NEW.environment_id,
  openpc.business_bytes(decode(substring(NEW.installation_digest FROM 8),'hex')),openpc.business_bytes(NEW.scope_cbor));
 IF openpc.business_cbor(NEW.admission_preimage) IS DISTINCT FROM expected OR NEW.admission_digest<>sha256(NEW.admission_preimage)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-DIGEST'; END IF;
 NEW.installed_at:=clock_timestamp();
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_envelope_scope_guard ON control.platform_envelope_scope;
CREATE TRIGGER platform_envelope_scope_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_envelope_scope
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_envelope_scope();


CREATE OR REPLACE FUNCTION openpc.platform_scope_document_value(scope jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE dimensions jsonb; slice jsonb; slices jsonb:='{}'; dimension_values jsonb;
 module_id integer; dimension integer; label text; key text;
BEGIN
 FOR module_id IN 1..2 LOOP
  dimensions:=scope->module_id::text; slice:='{}';
  FOR dimension IN 1..7 LOOP
   key:=(ARRAY['participantIds','privacyDomainIds','resourceIds','dataClasses','targetProfileIds','riskClasses',
    CASE WHEN module_id=1 THEN 'actionIntentIds' ELSE 'capabilityIds' END])[dimension];
   IF dimension IN(1,2) THEN
    SELECT coalesce(jsonb_agg(to_jsonb((substr(v->>'bytes',1,8)||'-'||substr(v->>'bytes',9,4)||'-'||
      substr(v->>'bytes',13,4)||'-'||substr(v->>'bytes',17,4)||'-'||substr(v->>'bytes',21,12))::uuid::text)
      ORDER BY ordinal),'[]'::jsonb) INTO dimension_values
     FROM jsonb_array_elements(dimensions->dimension::text) WITH ORDINALITY a(v,ordinal);
   ELSE dimension_values:=dimensions->dimension::text; END IF;
   slice:=slice||jsonb_build_object(key,dimension_values);
  END LOOP;
  label:=CASE WHEN module_id=1 THEN 'administration' ELSE 'runtime' END;
  slices:=slices||jsonb_build_object(label,slice);
 END LOOP;
 RETURN slices||jsonb_build_object('validFromNs',scope->>'3','validUntilNs',scope->>'4',
  'makerCheckerRequired',(scope->>'5')='1','stepUpRequired',(scope->>'6')='1','onwardDelegationDepth',(scope->>'7')::integer);
END $$;
REVOKE ALL ON FUNCTION openpc.platform_scope_document_value(jsonb) FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.platform_scope_document(p_bytes bytea)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 IF NOT openpc.identity_envelope_scope_valid(p_bytes) THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE'; END IF;
 RETURN openpc.platform_scope_document_value(openpc.business_cbor(p_bytes));
END $$;
REVOKE ALL ON FUNCTION openpc.platform_scope_document(bytea) FROM PUBLIC;

-- Complete conservative cohort within the installed finite runtime scope. An
-- unresolved original effect or in-flight activation blocks preparation.
CREATE OR REPLACE FUNCTION openpc.read_platform_scope_affected_targets(root_id uuid)
RETURNS TABLE(target jsonb) LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE pid uuid; privacy uuid; root control.platform_context; missing integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 IF root_id IS NULL OR openpc.current_action_intent_id() NOT IN('ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 SELECT * INTO STRICT root FROM control.platform_context p
  WHERE p.platform_context_id=root_id AND p.owner_participant_id=pid AND p.state='ACTIVE' FOR SHARE;
 PERFORM 1 FROM control.platform_envelope_scope s WHERE s.platform_context_id=root_id
  AND s.owner_participant_id=pid AND s.installation_privacy_domain_id=privacy;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN('PENDING','LEASED','RECONCILING'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-WORK-PENDING'; END IF;
 SELECT count(*) INTO missing FROM control.runtime_target t
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.active_generation_digest IS NOT NULL
   AND NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation o JOIN control.configuration_work w
    ON w.participant_id=o.participant_id AND w.privacy_domain_id=o.privacy_domain_id
      AND w.configuration_work_id=o.configuration_work_id AND w.execution_attempt_id=o.execution_attempt_id
      AND w.operation_id=o.operation_id AND w.runtime_target_id=o.runtime_target_id
      AND w.runtime_configuration_generation_id=o.runtime_configuration_generation_id
      AND w.generation_digest=o.generation_digest AND w.xds_version_digest=o.xds_version_digest
      AND w.state='COMPLETED' AND w.result_receipt_digest=o.activation_receipt_digest
    WHERE o.participant_id=pid AND o.privacy_domain_id=privacy AND o.runtime_target_id=t.runtime_target_id
      AND o.capsule_digest=t.active_generation_digest);
 IF missing<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-ORIGINAL-AMBIGUITY'; END IF;
 RETURN QUERY SELECT jsonb_build_object('participantId',pid::text,'privacyDomainId',privacy::text,
    'targetId',t.runtime_target_id::text,'expectedRevision',t.revision::text,
    'capsuleDigest',o.capsule_digest,'originalWorkId',o.configuration_work_id::text,
    'originalAttemptId',o.execution_attempt_id::text,'activationReceiptDigest',o.activation_receipt_digest)
  FROM control.runtime_target t JOIN control.runtime_activation_observation o
    ON o.participant_id=t.participant_id AND o.privacy_domain_id=t.privacy_domain_id
      AND o.runtime_target_id=t.runtime_target_id AND o.capsule_digest=t.active_generation_digest
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.active_generation_digest IS NOT NULL
  ORDER BY t.runtime_target_id;
END $$;
REVOKE ALL ON FUNCTION openpc.read_platform_scope_affected_targets(uuid) FROM PUBLIC;

-- The signed V2 receipt keeps this immutable original identity across exactly
-- one Root epoch. Normal preparation still creates and approves a new intent.
CREATE OR REPLACE FUNCTION openpc.platform_scope_pending_record_digest(r control.platform_scope_replacement)
RETURNS bytea LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object('candidate',r.candidate,
  'candidateDigest',encode(r.candidate_digest,'hex'),'successorScope',encode(r.successor_scope_cbor,'hex'),
  'successorPreimage',encode(r.successor_preimage,'hex'),'successorDigest',encode(r.successor_digest,'hex'),
  'state','WITHDRAWING','supersededBy',NULL,'commitOperationId',r.commit_operation_id,
  'commitCandidateId',r.commit_candidate_id,'commitApprovalId',r.commit_approval_id,'readinessDigest',encode(r.readiness_digest,'hex'))),'UTF8'))
$$;
REVOKE ALL ON FUNCTION openpc.platform_scope_pending_record_digest(control.platform_scope_replacement) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.platform_scope_pending_record_digest(control.platform_scope_replacement) TO openpc_control_owner;

CREATE OR REPLACE FUNCTION openpc.platform_scope_pending_root_bridge_current(r control.platform_scope_replacement,
 next_epoch numeric,next_revision numeric,next_digest bytea)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF to_regclass('control.root_expiry_recovery_scope') IS NULL THEN RETURN false; END IF;
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NOT openpc.matches_participant(r.participant_id) OR NOT openpc.matches_privacy(r.privacy_domain_id)
  OR NOT ((r.state='WITHDRAWING' AND r.row_version=1 AND r.superseded_by IS NULL)
    OR (r.state='SUPERSEDED' AND r.row_version=2 AND r.superseded_by IS NOT NULL))
  OR num_nonnulls(r.commit_operation_id,r.commit_candidate_id,r.commit_approval_id,r.readiness_digest,r.committed_at)<>0
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM control.root_expiry_recovery_scope s
 JOIN control.root_expiry_recovery_case c ON c.recovery_id=s.recovery_id AND c.participant_id=s.owner_participant_id
  AND c.privacy_domain_id=s.installation_privacy_domain_id AND c.state='COMPLETED' AND c.operation_id=s.activation_operation_id
  AND c.intent_digest=s.intent_digest AND c.enrollment_digest=s.enrollment_digest
  AND c.evidence_digest=sha256(c.evidence_cbor) AND octet_length(c.evidence_cose)>0
 JOIN control.root_expiry_recovery_enrollment e ON e.enrollment_id=c.enrollment_id AND e.participant_id=c.participant_id
  AND e.privacy_domain_id=c.privacy_domain_id AND e.document_digest=c.enrollment_digest AND e.row_version=c.enrollment_revision
  AND e.state='ACTIVE' AND e.document->>'schemaVersion'='2'
  AND e.document->>'purpose'='pc.installation.local-root-expiry-pending-recovery-custody.v2'
  AND e.document_digest=sha256(convert_to(openpc.signing_canonical_json(e.document),'UTF8'))
 JOIN control.root_expiry_recovery_trust t ON t.custody_trust_id=e.custody_trust_id AND t.document_digest=e.custody_trust_digest
  AND t.participant_id=e.participant_id AND t.privacy_domain_id=e.privacy_domain_id AND t.state='ACTIVE' AND t.row_version=1
  AND t.document->>'schemaVersion'='2' AND t.document->>'purpose'=e.document->>'purpose' AND t.document->'pending'=e.document->'pending'
 JOIN control.platform_context p ON p.platform_context_id=s.platform_context_id AND p.owner_participant_id=s.owner_participant_id
  AND p.state='ACTIVE' AND p.authority_epoch=s.platform_authority_epoch AND p.row_version=next_revision
 WHERE s.platform_context_id=r.platform_context_id AND s.owner_participant_id=r.participant_id AND s.installation_privacy_domain_id=r.privacy_domain_id
  AND s.platform_authority_epoch=next_epoch AND s.admission_digest=next_digest AND s.admission_digest=sha256(s.admission_preimage)
  AND s.predecessor_epoch=r.predecessor_epoch AND s.predecessor_digest=r.predecessor_digest AND next_epoch=r.predecessor_epoch+1
  AND next_revision=r.expected_root_revision+1 AND e.document->>'rootRevision'=r.expected_root_revision::text
  AND e.document->>'rootEpoch'=r.predecessor_epoch::text AND e.document->>'rootDigest'='sha256:'||encode(r.predecessor_digest,'hex')
  AND c.intent->>'schemaVersion'='2' AND c.intent->>'purpose'='LOCAL_ROOT_EXPIRY_PENDING_RECOVERY_ONLY'
  AND c.intent->'pending'=e.document->'pending'
  AND c.intent_digest=sha256(convert_to(openpc.signing_canonical_json(c.intent),'UTF8'))
  AND e.document#>>'{pending,replacementId}'=r.replacement_id::text
  AND e.document#>>'{pending,replacementRevision}'='1'
  AND e.document#>>'{pending,predecessorEpoch}'=r.predecessor_epoch::text
  AND e.document#>>'{pending,expectedRootRevision}'=r.expected_root_revision::text
  AND e.document#>>'{pending,predecessorDigest}'='sha256:'||encode(r.predecessor_digest,'hex')
  AND e.document#>>'{pending,preparationCandidateId}'=r.prepare_candidate_id::text
  AND e.document#>>'{pending,preparationOperationId}'=r.prepare_operation_id::text
  AND e.document#>>'{pending,preparationApprovalId}'=r.prepare_approval_id::text
  AND e.document#>>'{pending,preparationDigest}'='sha256:'||encode(r.candidate_digest,'hex')
  AND e.document#>>'{pending,successorDigest}'='sha256:'||encode(r.successor_digest,'hex')
  AND e.document#>>'{pending,pendingRecordDigest}'='sha256:'||encode(openpc.platform_scope_pending_record_digest(r),'hex')
  AND (e.document#>>'{pending,affectedTargetCount}')::integer=jsonb_array_length(r.candidate->'affectedTargets')
  AND (SELECT count(*) FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id)=jsonb_array_length(r.candidate->'affectedTargets')
  AND NOT EXISTS(SELECT 1 FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND NOT (r.candidate->'affectedTargets' @> jsonb_build_array(q.source)))
  AND (SELECT count(*) FROM control.root_expiry_recovery_proof proof WHERE proof.recovery_id=c.recovery_id
    AND proof.participant_id=c.participant_id AND proof.privacy_domain_id=c.privacy_domain_id AND proof.intent_digest=c.intent_digest)=4
  AND c.result=jsonb_build_object('rootEpoch',next_epoch::text,'rootRevision',next_revision::text,
    'rootDigest','sha256:'||encode(next_digest,'hex'),'operationId',s.activation_operation_id::text)
  AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=c.participant_id AND event.privacy_domain_id=c.privacy_domain_id
    AND event.aggregate_type='local-root-expiry-recovery' AND event.aggregate_id=c.recovery_id AND event.aggregate_sequence=1
    AND event.event_id=c.operation_id AND event.event_type='openpc.identity.local-root-expiry-recovery.completed.v1'
    AND event.payload_cbor=c.evidence_cbor AND event.payload_digest=c.evidence_digest AND event.cose_sign1=c.evidence_cose));
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;
REVOKE ALL ON FUNCTION openpc.platform_scope_pending_root_bridge_current(control.platform_scope_replacement,numeric,numeric,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.platform_scope_pending_root_bridge_current(control.platform_scope_replacement,numeric,numeric,bytea)
 TO openpc_control_owner,openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_platform_scope_replacement()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE root control.platform_context; initial control.platform_envelope_scope; base jsonb; expected jsonb; predecessor bytea; predecessor_scope bytea; current_scope jsonb; next_scope jsonb; dimension integer; readiness jsonb;
BEGIN
 IF TG_OP='DELETE' OR current_user<>'openpc_control_owner' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-OWNER'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT root FROM control.platform_context p WHERE p.platform_context_id=NEW.platform_context_id FOR UPDATE;
  SELECT * INTO STRICT initial FROM control.platform_envelope_scope s WHERE s.platform_context_id=root.platform_context_id;
  SELECT s.admission_digest,s.scope_cbor INTO STRICT predecessor,predecessor_scope FROM (
    SELECT platform_context_id,platform_authority_epoch,admission_digest,scope_cbor FROM control.platform_envelope_scope
    UNION ALL
    SELECT s.platform_context_id,s.platform_authority_epoch,s.admission_digest,s.scope_cbor
      FROM control.platform_envelope_scope_successor s JOIN control.platform_scope_replacement r
        ON r.replacement_id=s.replacement_id AND r.state='COMMITTED'
    UNION ALL SELECT platform_context_id,platform_authority_epoch,admission_digest,scope_cbor FROM control.root_expiry_recovery_scope
   ) s WHERE s.platform_context_id=root.platform_context_id AND s.platform_authority_epoch=root.authority_epoch;
  IF coalesce((root.owner_participant_id<>NEW.participant_id OR initial.installation_privacy_domain_id<>NEW.privacy_domain_id
    OR root.state<>'ACTIVE' OR root.authority_epoch<>NEW.predecessor_epoch OR root.row_version<>NEW.expected_root_revision
    OR NEW.state<>'WITHDRAWING' OR NEW.row_version<>1 OR NEW.prepare_operation_id<>openpc.current_operation_id()
    OR NEW.candidate->>'replacementId'<>NEW.replacement_id::text
    OR NEW.candidate->>'platformContextId'<>NEW.platform_context_id::text
    OR NEW.candidate->>'predecessorEpoch'<>NEW.predecessor_epoch::text
    OR NEW.candidate->>'expectedRootRevision'<>NEW.expected_root_revision::text
    OR NEW.candidate->>'predecessorDigest'<>'sha256:'||encode(NEW.predecessor_digest,'hex')
    OR NEW.candidate->'successorScope' IS DISTINCT FROM openpc.platform_scope_document(NEW.successor_scope_cbor)
    OR NEW.predecessor_digest IS DISTINCT FROM predecessor),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
  current_scope:=openpc.business_cbor(predecessor_scope); next_scope:=openpc.business_cbor(NEW.successor_scope_cbor);
  IF NOT coalesce(openpc.identity_envelope_scope_valid(NEW.successor_scope_cbor),false)
    OR coalesce(((next_scope->>'3')::numeric<(current_scope->>'3')::numeric
      OR (next_scope->>'4')::numeric>(current_scope->>'4')::numeric
      OR (next_scope->>'3')::numeric>extract(epoch from clock_timestamp())*1000000000
      OR (next_scope->>'4')::numeric<=extract(epoch from clock_timestamp())*1000000000
      OR next_scope->>'7'<>'0' OR next_scope=current_scope),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-BOUNDS'; END IF;
  FOR dimension IN 1..7 LOOP
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(next_scope->'2'->dimension::text) value
      WHERE NOT (current_scope->'2'->dimension::text @> jsonb_build_array(value)))
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RUNTIME-WIDENING'; END IF;
  END LOOP;
  IF (SELECT coalesce(jsonb_agg(entry ORDER BY entry->>'targetId'),'[]') FROM jsonb_array_elements(NEW.candidate->'affectedTargets') entry)
    IS DISTINCT FROM (SELECT coalesce(jsonb_agg(target ORDER BY target->>'targetId'),'[]')
      FROM openpc.read_platform_scope_affected_targets(NEW.platform_context_id))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
  base:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
    openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
    openpc.business_uuid(root.platform_context_id),openpc.business_uuid(root.owner_participant_id),
    openpc.business_uuid(initial.installation_privacy_domain_id),NEW.predecessor_epoch+1,initial.environment_id,
    openpc.business_bytes(decode(substring(initial.installation_digest FROM 8),'hex')),
    openpc.business_bytes(NEW.successor_scope_cbor));
  expected:=openpc.business_cbor(NEW.successor_preimage);
  IF jsonb_typeof(expected) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREIMAGE';
  END IF;
  IF coalesce((jsonb_array_length(expected)<>7
    OR expected->>0<>'pc.identity.platform-envelope-scope.successor.v1' OR expected->>1<>'1'
    OR expected->2 IS DISTINCT FROM openpc.business_uuid(NEW.replacement_id)
    OR expected->3 IS DISTINCT FROM openpc.business_uuid(NEW.prepare_operation_id)
    OR expected->>4<>NEW.predecessor_epoch::text
    OR expected->5 IS DISTINCT FROM openpc.business_bytes(NEW.predecessor_digest)
    OR openpc.business_cbor(decode(expected#>>'{6,bytes}','hex')) IS DISTINCT FROM base),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREIMAGE'; END IF;
 ELSIF NEW.state='SUPERSEDED' THEN
  -- Candidate visibility is bound to an inserted replacement by RLS. Validate
  -- its complete consumed provenance at the deferred boundary below, after
  -- both rows exist, without granting pre-insert candidate visibility.
  IF OLD.state<>'WITHDRAWING' OR OLD.row_version<>1 OR NEW.row_version<>2
    OR NEW.superseded_by IS NULL OR NEW.superseded_by=OLD.replacement_id
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.candidate->'administrators') a
      WHERE greatest((a#>>'{usable,validUntilNs}')::numeric,(a#>>'{grantable,validUntilNs}')::numeric)
        >extract(epoch from clock_timestamp())*1000000000)
    OR (to_jsonb(NEW)-'state'-'row_version'-'superseded_by') IS DISTINCT FROM
       (to_jsonb(OLD)-'state'-'row_version'-'superseded_by')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION'; END IF;
 ELSE
  readiness:=openpc.read_platform_scope_replacement_readiness(OLD.replacement_id);
  IF readiness->>'unacknowledgedTargets'<>'0' OR readiness->>'unpreparedAdministrators'<>'0'
    OR NEW.readiness_digest IS DISTINCT FROM decode(substring(readiness->>'readinessDigest' from 8),'hex')
    OR (readiness->>'sourceExpiresAtNs')::numeric<=(readiness->>'nowNs')::numeric
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-READINESS'; END IF;
  IF coalesce((OLD.state<>'WITHDRAWING' OR NEW.state<>'COMMITTED' OR NEW.row_version<>OLD.row_version+1
    OR NEW.commit_operation_id<>openpc.current_operation_id()
    OR (to_jsonb(NEW)-'state'-'row_version'-'commit_operation_id'-'commit_candidate_id'-'commit_approval_id'-'readiness_digest'-'committed_at')
      IS DISTINCT FROM (to_jsonb(OLD)-'state'-'row_version'-'commit_operation_id'-'commit_candidate_id'-'commit_approval_id'-'readiness_digest'-'committed_at')),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-HISTORY'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_platform_scope_replacement() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_replacement_guard ON control.platform_scope_replacement;
CREATE TRIGGER platform_scope_replacement_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_scope_replacement
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_scope_replacement();

CREATE OR REPLACE FUNCTION openpc.require_platform_scope_replacement_provenance()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE r control.platform_scope_replacement; phase text; operation uuid; candidate uuid; approval uuid; valid boolean;
BEGIN
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=NEW.replacement_id;
 IF TG_OP='UPDATE' AND NEW.state='SUPERSEDED' THEN
  -- Deferred: both rows and the successor's ordinary PREPARE provenance must
  -- commit together. The old intent, approvals and target evidence stay intact.
  IF NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement successor
    WHERE successor.replacement_id=r.superseded_by AND successor.participant_id=r.participant_id
      AND successor.privacy_domain_id=r.privacy_domain_id AND successor.platform_context_id=r.platform_context_id
      AND ((successor.predecessor_epoch=r.predecessor_epoch AND successor.expected_root_revision=r.expected_root_revision
        AND successor.predecessor_digest=r.predecessor_digest)
        OR openpc.platform_scope_pending_root_bridge_current(r,successor.predecessor_epoch,successor.expected_root_revision,successor.predecessor_digest))
      AND successor.prepare_operation_id=openpc.current_operation_id()
      AND successor.candidate->'supersedes'=jsonb_build_object('replacementId',r.replacement_id::text,
        'expectedRevision','1','successorDigest','sha256:'||encode(r.successor_digest,'hex')))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION-PROVENANCE'; END IF;
  RETURN NULL;
 END IF;
 phase:=CASE WHEN TG_OP='INSERT' THEN 'PREPARE' ELSE 'COMMIT' END;
 operation:=CASE WHEN phase='PREPARE' THEN r.prepare_operation_id ELSE r.commit_operation_id END;
 candidate:=CASE WHEN phase='PREPARE' THEN r.prepare_candidate_id ELSE r.commit_candidate_id END;
 approval:=CASE WHEN phase='PREPARE' THEN r.prepare_approval_id ELSE r.commit_approval_id END;
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate c
  JOIN control.approval_request a ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
    AND a.approval_request_id=approval AND a.subject_type='CONFIGURATION_CANDIDATE'
    AND a.subject_id=c.mutation_candidate_id AND a.subject_digest=c.candidate_digest
    AND a.subject_version=c.expected_revision AND a.state='APPROVED'
  JOIN control.mutation_evidence e ON e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
    AND e.operation_id=operation AND e.catalog_operation_id=c.catalog_operation_id
    AND e.aggregate_type='platform-scope-replacement' AND e.aggregate_id=r.replacement_id
    AND e.candidate_digest=c.candidate_digest AND e.approval_request_id=approval
    AND e.principal_id=c.maker_principal_id AND e.checker_principal_id<>e.principal_id
    AND e.mfa_challenge_id IS NOT NULL AND e.webauthn_assertion_binding_digest IS NOT NULL
  JOIN control.idempotency_record receipt ON receipt.participant_id=c.participant_id AND receipt.privacy_domain_id=c.privacy_domain_id
    AND receipt.operation_id=operation AND receipt.terminal_state='COMMITTED'
    AND receipt.result_payload->>'replacementId'=r.replacement_id::text
    AND receipt.result_payload->>'successorDigest'='sha256:'||encode(r.successor_digest,'hex')
  WHERE c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
    AND c.mutation_candidate_id=candidate AND c.consumed_operation_id=operation AND c.state='CONSUMED'
    AND c.catalog_operation_id='ID-OP-PLATFORM-SCOPE-'||phase AND c.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
    AND c.resource_id=r.replacement_id AND c.expected_revision=CASE WHEN phase='PREPARE' THEN 0 ELSE 1 END
    AND ((phase='PREPARE' AND c.candidate_document=r.candidate AND c.candidate_digest=r.candidate_digest)
      OR (phase='COMMIT' AND c.candidate_document->>'readinessDigest'='sha256:'||encode(r.readiness_digest,'hex')
        AND c.candidate_document->>'successorDigest'='sha256:'||encode(r.successor_digest,'hex')
        AND c.candidate_document->>'predecessorEpoch'=r.predecessor_epoch::text
        AND c.candidate_document->>'expectedRootRevision'=r.expected_root_revision::text))) INTO valid;
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PROVENANCE'; END IF;
 IF phase='PREPARE' AND (
  (SELECT count(*) FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id)<>jsonb_array_length(r.candidate->'affectedTargets')
  OR EXISTS(SELECT 1 FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND NOT (r.candidate->'affectedTargets' @> jsonb_build_array(q.source))))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
 IF phase='COMMIT' AND NOT EXISTS(SELECT 1 FROM control.platform_context p
    JOIN control.platform_envelope_scope_successor s ON s.platform_context_id=p.platform_context_id
      AND s.platform_authority_epoch=p.authority_epoch AND s.replacement_id=r.replacement_id
    WHERE p.platform_context_id=r.platform_context_id AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE'
      AND p.authority_epoch=r.predecessor_epoch+1 AND p.row_version=r.expected_root_revision+1)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-EFFECT'; END IF;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.require_platform_scope_replacement_provenance() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_replacement_provenance ON control.platform_scope_replacement;
CREATE CONSTRAINT TRIGGER platform_scope_replacement_provenance AFTER INSERT OR UPDATE ON control.platform_scope_replacement
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_platform_scope_replacement_provenance();

CREATE OR REPLACE FUNCTION openpc.guard_platform_scope_successor()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP<>'INSERT' OR current_user<>'openpc_control_owner'
  OR NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r
    JOIN control.platform_envelope_scope initial ON initial.platform_context_id=r.platform_context_id
    WHERE r.replacement_id=NEW.replacement_id AND r.state='COMMITTED' AND r.row_version=2
      AND r.commit_operation_id=openpc.current_operation_id()
      AND r.platform_context_id=NEW.platform_context_id AND NEW.platform_authority_epoch=r.predecessor_epoch+1
      AND NEW.preparation_operation_id=r.prepare_operation_id AND NEW.predecessor_epoch=r.predecessor_epoch
      AND NEW.predecessor_digest=r.predecessor_digest
      AND r.participant_id=NEW.owner_participant_id AND r.privacy_domain_id=NEW.installation_privacy_domain_id
      AND NEW.scope_cbor=r.successor_scope_cbor AND NEW.admission_preimage=r.successor_preimage
      AND NEW.admission_digest=r.successor_digest AND NEW.environment_id=initial.environment_id
      AND NEW.installation_digest=initial.installation_digest)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-IMMUTABLE-PLATFORM-SUCCESSOR'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_platform_scope_successor() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_successor_guard ON control.platform_envelope_scope_successor;
CREATE TRIGGER platform_scope_successor_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_envelope_scope_successor
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_scope_successor();

CREATE OR REPLACE FUNCTION openpc.prepare_platform_scope_replacement(document jsonb,scope bytea,preimage bytea,candidate_id uuid,approval_id uuid)
RETURNS TABLE(replacement jsonb) LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE inserted control.platform_scope_replacement; pending control.platform_scope_replacement; target_source jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('platform-scope-replacement:'||(document->>'platformContextId'),0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM 1 FROM control.runtime_target t WHERE t.participant_id=openpc.current_participant_id()
   AND t.privacy_domain_id=openpc.current_privacy_domain_id() ORDER BY t.runtime_target_id FOR SHARE;
 -- Serialize the old/new pending boundary with commits, before changing either.
 PERFORM 1 FROM control.platform_context WHERE platform_context_id=(document->>'platformContextId')::uuid
  AND owner_participant_id=openpc.current_participant_id() FOR UPDATE;
 SELECT * INTO pending FROM control.platform_scope_replacement r
  WHERE r.platform_context_id=(document->>'platformContextId')::uuid AND r.state='WITHDRAWING' FOR UPDATE;
 IF pending.replacement_id IS NULL THEN
  IF document ? 'supersedes' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION'; END IF;
 ELSE
  IF document->'supersedes' IS DISTINCT FROM jsonb_build_object('replacementId',pending.replacement_id::text,
      'expectedRevision',pending.row_version::text,'successorDigest','sha256:'||encode(pending.successor_digest,'hex'))
    OR pending.participant_id<>openpc.current_participant_id() OR pending.privacy_domain_id<>openpc.current_privacy_domain_id()
    OR (((pending.predecessor_epoch::text IS DISTINCT FROM document->>'predecessorEpoch'
      OR pending.expected_root_revision::text IS DISTINCT FROM document->>'expectedRootRevision'
      OR 'sha256:'||encode(pending.predecessor_digest,'hex') IS DISTINCT FROM document->>'predecessorDigest'))
      AND openpc.platform_scope_pending_root_bridge_current(pending,(document->>'predecessorEpoch')::numeric,
        (document->>'expectedRootRevision')::numeric,decode(substring(document->>'predecessorDigest' from 8),'hex')) IS DISTINCT FROM true)
    OR pending.replacement_id=(document->>'replacementId')::uuid
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION'; END IF;
  UPDATE control.platform_scope_replacement SET state='SUPERSEDED',row_version=2,
    superseded_by=(document->>'replacementId')::uuid WHERE replacement_id=pending.replacement_id;
 END IF;
 INSERT INTO control.platform_scope_replacement(replacement_id,platform_context_id,participant_id,privacy_domain_id,
  predecessor_epoch,expected_root_revision,predecessor_digest,candidate,candidate_digest,
  successor_scope_cbor,successor_preimage,successor_digest,prepare_operation_id,prepare_candidate_id,prepare_approval_id)
 VALUES((document->>'replacementId')::uuid,(document->>'platformContextId')::uuid,openpc.current_participant_id(),openpc.current_privacy_domain_id(),
  (document->>'predecessorEpoch')::numeric,(document->>'expectedRootRevision')::numeric,
  decode(substring(document->>'predecessorDigest' from 8),'hex'),document,
  sha256(convert_to(openpc.signing_canonical_json(document),'UTF8')),scope,preimage,sha256(preimage),openpc.current_operation_id(),candidate_id,approval_id)
 RETURNING * INTO STRICT inserted;
 FOR target_source IN SELECT v FROM jsonb_array_elements(document->'affectedTargets') v LOOP
  INSERT INTO control.platform_scope_target_withdrawal(replacement_id,participant_id,privacy_domain_id,runtime_target_id,source)
  VALUES(inserted.replacement_id,inserted.participant_id,inserted.privacy_domain_id,(target_source->>'targetId')::uuid,target_source);
 END LOOP;
 RETURN QUERY SELECT jsonb_build_object('replacementId',inserted.replacement_id::text,'successorDigest','sha256:'||encode(inserted.successor_digest,'hex'),
   'state',inserted.state,'revision',inserted.row_version::text,'operationId',inserted.prepare_operation_id::text);
END $$;
REVOKE ALL ON FUNCTION openpc.prepare_platform_scope_replacement(jsonb,bytea,bytea,uuid,uuid) FROM PUBLIC;


CREATE OR REPLACE FUNCTION openpc.read_platform_scope_replacement_readiness(wanted uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE r control.platform_scope_replacement; root control.platform_context; targets jsonb; admins jsonb; bindings jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 PERFORM openpc.assert_runtime_target_disposition_owner();
 IF openpc.current_action_intent_id() NOT IN('ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=wanted
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT root FROM control.platform_context p WHERE p.platform_context_id=r.platform_context_id
  AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE';
 IF r.state<>'WITHDRAWING' OR r.row_version<>1 OR root.authority_epoch<>r.predecessor_epoch
  OR root.row_version<>r.expected_root_revision THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('targetId',q.runtime_target_id::text,'source',q.source,
  'revision',head.revision::text,'deliveryDigest',d.delivery_digest,'acknowledgementDigest',a.acknowledgement_digest,
  'journalSequence',a.claims->>'journal_sequence','ready',coalesce(
    head.binding->>'action'='Withdraw' AND head.binding->'cause'=jsonb_build_object('kind','Dependency','owner','Platform',
      'resource_id',r.replacement_id::text,'operation_id',r.prepare_operation_id::text,'revision',1)
    AND 'sha256:'||(head.binding#>>'{source,capsule_digest}')=q.source->>'capsuleDigest'
    AND head.binding#>>'{source,original_work_id}'=q.source->>'originalWorkId'
    AND head.binding#>>'{source,original_execution_attempt_id}'=q.source->>'originalAttemptId'
    AND d.claims=head.binding||jsonb_build_object('committed_admission_digest',substring(head.admission_digest from 8))
    AND a.claims->>'installed_state'='NewUseDenied' AND a.claims->'target'=head.binding->'target'
    AND a.claims->>'delivery_digest'=substring(d.delivery_digest from 8)
    AND EXISTS(SELECT 1 FROM control.credential credential JOIN control.principal principal
      ON principal.participant_id=credential.participant_id AND principal.principal_id=credential.principal_id
      WHERE credential.participant_id=q.participant_id AND credential.credential_id=(head.binding#>>'{target,credential_id}')::uuid
        AND credential.kind='WORKLOAD_MTLS' AND credential.state='ACTIVE' AND principal.state='ACTIVE'
        AND credential.principal_id=(head.binding#>>'{target,principal_id}')::uuid
        AND credential.credential_epoch::text=head.binding#>>'{target,credential_epoch}'
        AND principal.authority_epoch::text=head.binding#>>'{target,principal_epoch}'
        AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp()))
    AND (a.claims->>'disposition_revision')::bigint=head.revision
    AND d.delivery_digest='sha256:'||encode(sha256(d.signed_delivery),'hex')
    AND a.acknowledgement_digest='sha256:'||encode(sha256(a.signed_acknowledgement),'hex'),false))
    ORDER BY q.runtime_target_id),'[]') INTO targets
 FROM control.platform_scope_target_withdrawal q
 LEFT JOIN LATERAL(SELECT h.* FROM control.runtime_target_disposition_admission h WHERE h.participant_id=q.participant_id
  AND h.privacy_domain_id=q.privacy_domain_id AND h.runtime_target_id=q.runtime_target_id ORDER BY h.revision DESC LIMIT 1) head ON true
 LEFT JOIN control.runtime_target_disposition_delivery d ON d.participant_id=q.participant_id AND d.privacy_domain_id=q.privacy_domain_id
  AND d.runtime_target_id=q.runtime_target_id AND d.revision=head.revision
 LEFT JOIN control.runtime_target_disposition_acknowledgement a ON a.participant_id=q.participant_id AND a.privacy_domain_id=q.privacy_domain_id
  AND a.runtime_target_id=q.runtime_target_id AND a.delivery_digest=d.delivery_digest
 WHERE q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id AND q.replacement_id=r.replacement_id;
 IF jsonb_array_length(targets)<>jsonb_array_length(r.candidate->'affectedTargets')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
 SELECT jsonb_agg(jsonb_build_object('principalId',plan->>'principalId','envelopeId',plan->>'envelopeId',
  'assignmentId',plan->>'assignmentId','envelopeDigest','sha256:'||encode(e.semantic_digest,'hex'),
  'signatureDigest','sha256:'||encode(sha256(e.cose_sign1),'hex'),'assignmentRevision',a.row_version::text,
  'roleRevision',role.row_version::text,'ready',coalesce(
    e.state='ACTIVE' AND e.representation='TYPED_V1' AND e.platform_context_id=r.platform_context_id
    AND e.platform_authority_epoch=r.predecessor_epoch+1 AND e.maker_checker_required AND e.step_up_required
    AND e.onward_delegation_depth=0 AND cardinality(e.runtime_capability_ids)=0
    AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp() AND octet_length(e.cose_sign1)>0
    AND p.state='APPROVED' AND p.row_version=3 AND p.proposal_cbor=e.semantic_cbor
    AND create_intent.state='CONSUMED' AND create_intent.candidate_document->>'platformScopeReplacementId'=r.replacement_id::text
    AND create_intent.candidate_document->'usable'=plan->'usable' AND create_intent.candidate_document->'grantable'=plan->'grantable'
    AND openpc.platform_scope_document_value(openpc.business_cbor(p.proposal_cbor)->'8')=plan->'usable'
    AND openpc.platform_scope_document_value(openpc.business_cbor(p.proposal_cbor)->'9')=plan->'grantable'
    AND activation.state='COMMITTED' AND activation.row_version=4 AND activation.cose_sign1=e.cose_sign1
    AND principal.state='ACTIVE' AND principal.kind IN('USER','PLATFORM_OPERATOR')
    AND role.state='ACTIVE' AND role.row_version::text=plan->>'expectedRoleRevision'
    AND plan->>'roleDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
      'domain','pc.identity.envelope-role-binding.v1','participantId',r.participant_id::text,
      'role',jsonb_build_object('roleId',role.role_id,'version',role.row_version::text,'actions',role.action_intent_ids,
       'origin',role.origin,'createdByPrincipalId',role.created_by_principal_id::text,'creatorParticipantId',role.creator_participant_id::text,
       'bootstrapMandateId',role.bootstrap_mandate_id::text,'bootstrapPlatformParticipantId',role.bootstrap_platform_participant_id::text))),'UTF8')),'hex')
    AND a.state='ACTIVE' AND a.principal_id=principal.principal_id AND a.authority_envelope_id=e.authority_envelope_id
    AND a.role_id=role.role_id AND a.authority_group_id IS NULL AND a.delegation_epoch=e.delegation_epoch
    AND a.valid_during=tstzrange(e.valid_from,e.valid_until,'[)') AND a.valid_during @> clock_timestamp()
    AND a.privacy_domain_ids=e.privacy_domain_ids AND a.action_intent_ids=e.action_intent_ids AND a.resource_ids=e.resource_ids
    AND a.risk_classes=e.risk_classes AND cardinality(a.runtime_capability_ids)=0
    AND a.maker_checker_required AND a.step_up_required AND a.onward_delegation_depth=0,false))
    ORDER BY plan->>'principalId') INTO admins
 FROM jsonb_array_elements(r.candidate->'administrators') plan
 LEFT JOIN control.authority_envelope e ON e.participant_id=r.participant_id AND e.authority_envelope_id=(plan->>'envelopeId')::uuid
 LEFT JOIN control.identity_envelope_proposal p ON p.participant_id=r.participant_id AND p.privacy_domain_id=r.privacy_domain_id AND p.envelope_id=e.authority_envelope_id
 LEFT JOIN control.mutation_candidate create_intent ON create_intent.participant_id=r.participant_id AND create_intent.mutation_candidate_id=p.create_candidate_id
 LEFT JOIN control.identity_envelope_activation activation ON activation.participant_id=r.participant_id AND activation.privacy_domain_id=r.privacy_domain_id
  AND activation.envelope_id=e.authority_envelope_id AND activation.operation_id=e.last_mutation_operation_id
 LEFT JOIN control.assignment a ON a.participant_id=r.participant_id AND a.assignment_id=(plan->>'assignmentId')::uuid
 LEFT JOIN control.authority_role role ON role.participant_id=r.participant_id AND role.authority_role_id=(plan->>'roleId')::uuid
 LEFT JOIN control.principal principal ON principal.participant_id=r.participant_id AND principal.principal_id=(plan->>'principalId')::uuid;
 bindings:=jsonb_build_object('replacementId',r.replacement_id::text,'platformContextId',r.platform_context_id::text,
  'rootRevision',root.row_version::text,'predecessorEpoch',r.predecessor_epoch::text,'predecessorDigest','sha256:'||encode(r.predecessor_digest,'hex'),
  'successorDigest','sha256:'||encode(r.successor_digest,'hex'),'replacementRevision',r.row_version::text,'state',r.state,
  'targets',targets,'administrators',admins,'sourceExpiresAtNs',openpc.business_cbor(r.successor_scope_cbor)->>'4');
 RETURN bindings||jsonb_build_object('readinessDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('domain','pc.identity.platform-scope-readiness.v1','source',bindings)),'UTF8')),'hex'),
  'unacknowledgedTargets',(SELECT count(*) FROM jsonb_array_elements(targets) t WHERE t->>'ready' IS DISTINCT FROM 'true'),
  'unpreparedAdministrators',(SELECT count(*) FROM jsonb_array_elements(admins) a WHERE a->>'ready' IS DISTINCT FROM 'true'),
  'nowNs',(floor(extract(epoch from clock_timestamp())*1000000)*1000)::text);
END $$;
REVOKE ALL ON FUNCTION openpc.read_platform_scope_replacement_readiness(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.commit_platform_scope_replacement(document jsonb,candidate_id uuid,approval_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE r control.platform_scope_replacement; initial control.platform_envelope_scope; current_root control.platform_context; readiness jsonb; queued record;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('platform-scope-replacement:'||(document->>'platformContextId'),0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=(document->>'replacementId')::uuid
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() FOR UPDATE;
 SELECT * INTO STRICT current_root FROM control.platform_context p WHERE p.platform_context_id=r.platform_context_id
  AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE' FOR UPDATE;
 FOR queued IN SELECT q.runtime_target_id FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
  AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id ORDER BY q.runtime_target_id LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||r.participant_id::text||':'||r.privacy_domain_id::text||':'||queued.runtime_target_id::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 readiness:=openpc.read_platform_scope_replacement_readiness(r.replacement_id);
 IF coalesce((document->>'platformContextId'<>readiness->>'platformContextId'
   OR document->>'expectedRootRevision'<>readiness->>'rootRevision'
   OR document->>'expectedReplacementRevision'<>readiness->>'replacementRevision'
   OR document->>'predecessorEpoch'<>readiness->>'predecessorEpoch'
   OR document->>'predecessorDigest'<>readiness->>'predecessorDigest'
   OR document->>'successorDigest'<>readiness->>'successorDigest' OR document->>'readinessDigest'<>readiness->>'readinessDigest'
   OR readiness->>'unacknowledgedTargets'<>'0' OR readiness->>'unpreparedAdministrators'<>'0'
   OR (readiness->>'sourceExpiresAtNs')::numeric<=(readiness->>'nowNs')::numeric),true)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-READINESS'; END IF;
 SELECT * INTO STRICT initial FROM control.platform_envelope_scope s WHERE s.platform_context_id=r.platform_context_id;
 UPDATE control.platform_scope_replacement SET state='COMMITTED',row_version=2,commit_operation_id=openpc.current_operation_id(),
  commit_candidate_id=candidate_id,commit_approval_id=approval_id,readiness_digest=decode(substring(document->>'readinessDigest' from 8),'hex'),
  committed_at=clock_timestamp() WHERE replacement_id=r.replacement_id;
 INSERT INTO control.platform_envelope_scope_successor(platform_context_id,platform_authority_epoch,owner_participant_id,installation_privacy_domain_id,
  replacement_id,preparation_operation_id,predecessor_epoch,predecessor_digest,environment_id,installation_digest,scope_cbor,admission_preimage,admission_digest)
 VALUES(r.platform_context_id,r.predecessor_epoch+1,r.participant_id,r.privacy_domain_id,r.replacement_id,r.prepare_operation_id,
  r.predecessor_epoch,r.predecessor_digest,initial.environment_id,initial.installation_digest,r.successor_scope_cbor,r.successor_preimage,r.successor_digest);
 UPDATE control.platform_context SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE platform_context_id=r.platform_context_id AND authority_epoch=r.predecessor_epoch AND row_version=r.expected_root_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
 RETURN jsonb_build_object('replacementId',r.replacement_id::text,'successorDigest','sha256:'||encode(r.successor_digest,'hex'),
  'state','COMMITTED','revision','2','operationId',openpc.current_operation_id()::text,'platformAuthorityEpoch',(r.predecessor_epoch+1)::text);
END $$;
REVOKE ALL ON FUNCTION openpc.commit_platform_scope_replacement(jsonb,uuid,uuid) FROM PUBLIC;

DROP POLICY IF EXISTS platform_scope_replacement_root_commit ON control.platform_context;
CREATE POLICY platform_scope_replacement_root_commit ON control.platform_context FOR UPDATE TO openpc_control_owner
 USING(openpc.matches_participant(owner_participant_id) AND openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 WITH CHECK(openpc.matches_participant(owner_participant_id) AND openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  AND state='ACTIVE' AND EXISTS(SELECT 1 FROM control.platform_scope_replacement r WHERE r.platform_context_id=platform_context.platform_context_id
    AND r.participant_id=platform_context.owner_participant_id AND r.state='COMMITTED'
    AND r.commit_operation_id=openpc.current_operation_id() AND r.predecessor_epoch+1=platform_context.authority_epoch
    AND r.expected_root_revision+1=platform_context.row_version));


CREATE OR REPLACE FUNCTION openpc.reject_platform_scope_truncate()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-HISTORY'; END $$;
REVOKE ALL ON FUNCTION openpc.reject_platform_scope_truncate() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_replacement_truncate ON control.platform_scope_replacement;
CREATE TRIGGER platform_scope_replacement_truncate BEFORE TRUNCATE ON control.platform_scope_replacement
 FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_platform_scope_truncate();
DROP TRIGGER IF EXISTS platform_scope_successor_truncate ON control.platform_envelope_scope_successor;
CREATE TRIGGER platform_scope_successor_truncate BEFORE TRUNCATE ON control.platform_envelope_scope_successor
 FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_platform_scope_truncate();


CREATE OR REPLACE FUNCTION openpc.discovery_approval_resume_source_compatible(old_source jsonb,new_source jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE expected jsonb:=old_source; actions jsonb; i integer; scope text; old_actions jsonb;
BEGIN
 IF jsonb_typeof(old_source) IS DISTINCT FROM 'object' OR jsonb_typeof(new_source) IS DISTINCT FROM 'object'
  OR jsonb_typeof(old_source->'originalAdministrators') IS DISTINCT FROM 'array'
  OR jsonb_typeof(new_source->'originalAdministrators') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF jsonb_array_length(old_source->'originalAdministrators')<>2
  OR jsonb_array_length(new_source->'originalAdministrators')<>2 THEN RETURN false; END IF;
 actions:=jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1');
 old_actions:=old_source#>'{originalAdministrators,0,usable,administration,actionIntentIds}';
 IF old_actions IS DISTINCT FROM jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1') AND old_actions IS DISTINCT FROM actions THEN RETURN false; END IF;
 FOR i IN 0..1 LOOP
  FOREACH scope IN ARRAY ARRAY['usable','grantable'] LOOP
   IF old_source#>ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'] IS DISTINCT FROM old_actions
    OR new_source#>ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'] IS DISTINCT FROM actions
   THEN RETURN false; END IF;
   expected:=jsonb_set(expected,ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'],actions,false);
  END LOOP;
 END LOOP;
 RETURN expected=new_source;
END $$;
REVOKE ALL ON FUNCTION openpc.discovery_approval_resume_source_compatible(jsonb,jsonb) FROM PUBLIC;

-- Enrolled descendants may recover an unconsumed original intent. Raw source
-- equality is unchanged; only the installed, completed Root receipt chain can
-- establish the additional provenance. This predicate grants no authority.
CREATE OR REPLACE FUNCTION openpc.discovery_approval_resume_enrollments_compatible(p_old uuid,p_new uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE old_e control.platform_recovery_enrollment; new_e control.platform_recovery_enrollment;
 old_source jsonb; new_source jsonb; old_refs jsonb; new_refs jsonb; suffix jsonb; reference jsonb;
 delta integer; i integer; receipt record; previous_document jsonb; runtime_scope jsonb;
BEGIN
 SELECT * INTO old_e FROM control.platform_recovery_enrollment WHERE enrollment_id=p_old;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO new_e FROM control.platform_recovery_enrollment WHERE enrollment_id=p_new;
 IF NOT FOUND THEN RETURN false; END IF;
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NOT openpc.matches_participant(new_e.participant_id) OR NOT openpc.matches_privacy(new_e.privacy_domain_id)
  OR row(new_e.participant_id,new_e.privacy_domain_id,new_e.platform_context_id,new_e.source_purpose)
    IS DISTINCT FROM row(old_e.participant_id,old_e.privacy_domain_id,old_e.platform_context_id,old_e.source_purpose)
  OR old_e.source_purpose IS DISTINCT FROM 'ROOT_EXPIRY_RECOVERY'
  OR old_e.document->>'schema' IS DISTINCT FROM 'pc.identity.discovery-certificate-recovery-enrollment'
  OR new_e.document->>'schema' IS DISTINCT FROM old_e.document->>'schema'
  OR old_e.document->>'schemaVersion' IS DISTINCT FROM '2' OR new_e.document->>'schemaVersion' IS DISTINCT FROM '2'
  OR old_e.document->>'assurance' IS DISTINCT FROM 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'
  OR new_e.document->>'assurance' IS DISTINCT FROM old_e.document->>'assurance'
  OR new_e.document->'certificateRecovery' IS DISTINCT FROM old_e.document->'certificateRecovery'
  OR new_e.document->'administratorPrincipalIds' IS DISTINCT FROM old_e.document->'administratorPrincipalIds'
  OR new_e.document_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(new_e.document),'UTF8'))
  OR old_e.document_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(old_e.document),'UTF8'))
  OR new_e.state IS DISTINCT FROM 'ACTIVE' OR new_e.row_version<>1
  OR new_e.valid_from>clock_timestamp() OR new_e.valid_until<=clock_timestamp()
  OR openpc.platform_recovery_source_root_current(new_e) IS DISTINCT FROM true
 THEN RETURN false; END IF;
 old_source:=old_e.document->'source'; new_source:=new_e.document->'source';
 IF row(new_e.root_epoch,new_e.root_revision,new_e.root_digest)=row(old_e.root_epoch,old_e.root_revision,old_e.root_digest)
 THEN RETURN openpc.discovery_approval_resume_source_compatible(old_source,new_source); END IF;
 IF new_e.root_epoch<=old_e.root_epoch OR new_e.root_epoch-old_e.root_epoch>31
  OR new_e.root_revision-old_e.root_revision IS DISTINCT FROM new_e.root_epoch-old_e.root_epoch
  OR jsonb_typeof(old_source) IS DISTINCT FROM 'object' OR jsonb_typeof(new_source) IS DISTINCT FROM 'object'
  OR old_source->>'kind' IS DISTINCT FROM 'ROOT_EXPIRY_RECOVERY' OR new_source->>'kind' IS DISTINCT FROM old_source->>'kind'
  OR (new_source-ARRAY['recoveryId','enrollmentId','activationOperationId','receiptDigest','ancestorReceipts','originalAdministrators'])
    IS DISTINCT FROM (old_source-ARRAY['recoveryId','enrollmentId','activationOperationId','receiptDigest','ancestorReceipts','originalAdministrators'])
  OR openpc.discovery_approval_resume_source_compatible(old_source,
    old_source||jsonb_build_object('originalAdministrators',new_source->'originalAdministrators')) IS DISTINCT FROM true
 THEN RETURN false; END IF;
 delta:=(new_e.root_epoch-old_e.root_epoch)::integer;
 old_refs:=jsonb_build_array(old_source-ARRAY['kind','originalAdministrators','ancestorReceipts'])||coalesce(old_source->'ancestorReceipts','[]'::jsonb);
 new_refs:=jsonb_build_array(new_source-ARRAY['kind','originalAdministrators','ancestorReceipts'])||coalesce(new_source->'ancestorReceipts','[]'::jsonb);
 IF jsonb_typeof(old_refs) IS DISTINCT FROM 'array' OR jsonb_typeof(new_refs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(new_refs)>32 OR jsonb_array_length(new_refs)<>jsonb_array_length(old_refs)+delta
 THEN RETURN false; END IF;
 SELECT jsonb_agg(value ORDER BY ordinality) INTO suffix FROM jsonb_array_elements(new_refs) WITH ORDINALITY WHERE ordinality>delta;
 IF suffix IS DISTINCT FROM old_refs THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(new_refs)-1 LOOP
  reference:=new_refs->i;
  SELECT recovery.result,recovery.intent,original.document,scope.admission_digest INTO receipt
   FROM control.root_expiry_recovery_case recovery
   JOIN control.root_expiry_recovery_enrollment original ON original.enrollment_id=recovery.enrollment_id
    AND original.participant_id=recovery.participant_id AND original.privacy_domain_id=recovery.privacy_domain_id
    AND original.row_version=recovery.enrollment_revision AND original.document_digest=recovery.enrollment_digest
   JOIN control.root_expiry_recovery_scope scope ON scope.recovery_id=recovery.recovery_id
    AND scope.platform_context_id=new_e.platform_context_id AND scope.owner_participant_id=recovery.participant_id
    AND scope.installation_privacy_domain_id=recovery.privacy_domain_id AND scope.activation_operation_id=recovery.operation_id
    AND scope.platform_authority_epoch=new_e.root_epoch-i
   WHERE recovery.recovery_id::text=reference->>'recoveryId' AND recovery.enrollment_id::text=reference->>'enrollmentId'
    AND recovery.operation_id::text=reference->>'activationOperationId'
    AND 'sha256:'||encode(recovery.evidence_digest,'hex')=reference->>'receiptDigest'
    AND recovery.participant_id=new_e.participant_id AND recovery.privacy_domain_id=new_e.privacy_domain_id
    AND recovery.state='COMPLETED' AND recovery.evidence_digest=sha256(recovery.evidence_cbor)
    AND recovery.intent_digest=sha256(convert_to(openpc.signing_canonical_json(recovery.intent),'UTF8'))
    AND original.document_digest=sha256(convert_to(openpc.signing_canonical_json(original.document),'UTF8'));
  IF NOT FOUND THEN RETURN false; END IF;
  IF receipt.result->>'rootEpoch' IS DISTINCT FROM (new_e.root_epoch-i)::text
   OR receipt.result->>'rootRevision' IS DISTINCT FROM (new_e.root_revision-i)::text
   OR receipt.result->>'rootDigest' IS DISTINCT FROM 'sha256:'||encode(receipt.admission_digest,'hex')
   OR receipt.document->>'rootEpoch' IS DISTINCT FROM (new_e.root_epoch-i-1)::text
   OR receipt.document->>'rootRevision' IS DISTINCT FROM (new_e.root_revision-i-1)::text
   OR receipt.document->>'platformContextId' IS DISTINCT FROM new_e.platform_context_id::text
   OR receipt.document->'administratorPrincipalIds' IS DISTINCT FROM new_e.document->'administratorPrincipalIds'
  THEN RETURN false; END IF;
  IF i=0 THEN
   IF receipt.admission_digest IS DISTINCT FROM new_e.root_digest THEN RETURN false; END IF;
   runtime_scope:=receipt.intent#>'{successorScope,runtime}';
  ELSE
   IF previous_document->>'rootDigest' IS DISTINCT FROM receipt.result->>'rootDigest'
    OR previous_document->>'installationDigest' IS DISTINCT FROM receipt.document->>'installationDigest'
    OR previous_document->>'installationEnvironmentId' IS DISTINCT FROM receipt.document->>'installationEnvironmentId'
    OR receipt.intent#>'{successorScope,runtime}' IS DISTINCT FROM runtime_scope
   THEN RETURN false; END IF;
  END IF;
  IF i=delta AND receipt.admission_digest IS DISTINCT FROM old_e.root_digest THEN RETURN false; END IF;
  previous_document:=receipt.document;
 END LOOP;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION openpc.discovery_approval_resume_enrollments_compatible(uuid,uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.discovery_certificate_resume_administrators_current(p_enrollment uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
 SELECT coalesce(EXISTS(SELECT 1 FROM control.platform_recovery_enrollment e
 WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
  AND e.source_purpose='ROOT_EXPIRY_RECOVERY' AND e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
  AND e.document->>'schemaVersion'='2' AND e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
  AND current_setting('openpc.local_qa_runtime',true)='1'
  AND jsonb_array_length(e.document#>'{source,originalAdministrators}')=2
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(e.document#>'{source,originalAdministrators}') a
   WHERE a#>'{usable,administration,actionIntentIds}' IS DISTINCT FROM jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1')
    OR a#>'{grantable,administration,actionIntentIds}' IS DISTINCT FROM jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'))
  AND openpc.platform_recovery_source_root_current(e) AND openpc.platform_recovery_original_administrators_current(e)),false)
$$;
REVOKE ALL ON FUNCTION openpc.discovery_certificate_resume_administrators_current(uuid) FROM PUBLIC;

/** Read-only exact historical subject relation; neither existence nor the
 * source delta grants authority. The supported installation and current lease
 * owners still qualify all original Role/envelope/assignment rights. */
CREATE OR REPLACE FUNCTION openpc.discovery_approval_resume_subject_visible(p_participant uuid,p_privacy uuid,p_principal uuid,p_envelope uuid,p_approval uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
 SELECT coalesce(EXISTS(SELECT 1 FROM control.approval_request approval
  JOIN control.mutation_candidate c ON c.participant_id=approval.participant_id AND c.privacy_domain_id=approval.privacy_domain_id
   AND c.mutation_candidate_id=approval.subject_id AND c.candidate_digest=approval.subject_digest
   AND c.expected_revision=approval.subject_version AND c.action_intent_id=approval.action_intent_id
   AND c.maker_principal_id=approval.maker_principal_id
  JOIN control.authority_envelope old_e ON old_e.participant_id=c.participant_id AND old_e.authority_envelope_id=c.maker_authority_envelope_id
   AND old_e.principal_id=c.maker_principal_id AND old_e.representation='RECOVERY_V1'
  JOIN control.platform_recovery_case old_case ON old_case.participant_id=c.participant_id AND old_case.privacy_domain_id=c.privacy_domain_id
   AND old_case.recovery_id=old_e.recovery_case_id AND old_case.state='EXPIRED' AND old_case.valid_until<=clock_timestamp()
   AND old_case.completion_operation_id IS NULL AND old_case.completion_result IS NULL
  JOIN control.platform_recovery_enrollment old_source ON old_source.enrollment_id=old_case.enrollment_id
   AND old_source.participant_id=c.participant_id AND old_source.privacy_domain_id=c.privacy_domain_id
   AND old_source.row_version=old_case.enrollment_revision AND old_source.document_digest=old_case.enrollment_digest
  JOIN control.authority_envelope e ON e.participant_id=c.participant_id AND e.authority_envelope_id=p_envelope
   AND e.principal_id=c.maker_principal_id AND e.representation='RECOVERY_V1'
  JOIN control.platform_recovery_case fresh ON fresh.participant_id=c.participant_id AND fresh.privacy_domain_id=c.privacy_domain_id
   AND fresh.recovery_id=e.recovery_case_id AND fresh.recovery_id<>old_case.recovery_id AND fresh.state='ACTIVE'
   AND fresh.valid_from<=clock_timestamp() AND fresh.valid_until>clock_timestamp()
   AND fresh.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent' AND fresh.intent->>'schemaVersion'='2'
   AND fresh.intent->'certificateRecovery'=old_case.intent->'certificateRecovery'
   AND ((fresh.intent#>'{administrators,0}')-'principalEpoch')=((old_case.intent#>'{administrators,0}')-'principalEpoch')
   AND ((fresh.intent#>'{administrators,1}')-'principalEpoch')=((old_case.intent#>'{administrators,1}')-'principalEpoch')
  JOIN control.platform_recovery_enrollment source ON source.enrollment_id=fresh.enrollment_id
   AND source.participant_id=c.participant_id AND source.privacy_domain_id=c.privacy_domain_id
   AND source.row_version=fresh.enrollment_revision AND source.document_digest=fresh.enrollment_digest
  WHERE c.participant_id=p_participant AND c.privacy_domain_id=p_privacy AND c.maker_principal_id=p_principal
   AND openpc.matches_participant(c.participant_id) AND openpc.matches_privacy(c.privacy_domain_id)
   AND current_setting('openpc.local_qa_runtime',true)='1'
   AND approval.approval_request_id=p_approval AND approval.subject_type='CONFIGURATION_CANDIDATE'
   AND approval.state IN ('OPEN','APPROVED','EXPIRED') AND approval.checker_principal_id<>c.maker_principal_id
   AND approval.checker_principal_id::text=fresh.intent#>>'{administrators,1,principalId}'
   AND c.state IN ('APPROVAL_REQUESTED','APPROVED') AND c.consumed_operation_id IS NULL
   AND (c.catalog_operation_id,c.action_intent_id,c.resource_type,c.operation_class)=
     ('ID-OP-WORKLOAD-ROTATE','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','participant','UPDATE')
   AND old_case.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   AND c.resource_id::text=fresh.intent#>>'{certificateRecovery,predecessorCredentialId}'
   AND c.expected_revision::text=fresh.intent#>>'{certificateRecovery,predecessorRevision}'
   AND c.candidate_document=jsonb_build_object('replacedCredentialId',c.resource_id::text,
     'credentialId',fresh.intent#>>'{certificateRecovery,successorCredentialId}',
     'publicKeySpkiDer',fresh.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
   AND c.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(c.candidate_document),'UTF8'))
   AND source.source_purpose='ROOT_EXPIRY_RECOVERY' AND source.document->>'schemaVersion'='2'
   AND old_source.source_purpose=source.source_purpose AND source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
   AND old_source.document->>'assurance'=source.document->>'assurance'
   AND source.document->'certificateRecovery'=old_source.document->'certificateRecovery'
   AND source.document->'administratorPrincipalIds'=old_source.document->'administratorPrincipalIds'
   AND openpc.discovery_approval_resume_enrollments_compatible(old_source.enrollment_id,source.enrollment_id)
   AND old_source.document_digest=sha256(convert_to(openpc.signing_canonical_json(old_source.document),'UTF8'))
   AND source.document_digest=sha256(convert_to(openpc.signing_canonical_json(source.document),'UTF8'))
   AND openpc.platform_recovery_envelope_current(e.authority_envelope_id)),false)
$$;
REVOKE ALL ON FUNCTION openpc.discovery_approval_resume_subject_visible(uuid,uuid,uuid,uuid,uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.discovery_approval_resume_eligible(p_participant uuid,p_privacy uuid,p_principal uuid,p_envelope uuid,p_approval uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
 SELECT openpc.discovery_approval_resume_subject_visible(p_participant,p_privacy,p_principal,p_envelope,p_approval)
 AND NOT EXISTS(SELECT 1 FROM control.approval_request a JOIN control.mutation_candidate child
  ON child.participant_id=a.participant_id AND child.privacy_domain_id=a.privacy_domain_id AND child.predecessor_candidate_id=a.subject_id
  WHERE a.participant_id=p_participant AND a.privacy_domain_id=p_privacy AND a.approval_request_id=p_approval)
$$;
REVOKE ALL ON FUNCTION openpc.discovery_approval_resume_eligible(uuid,uuid,uuid,uuid,uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.assert_discovery_approval_resume(n control.mutation_candidate)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE old_attempt control.mutation_candidate; previous control.platform_recovery_case;
 fresh control.platform_recovery_case; old_enrollment control.platform_recovery_enrollment;
 new_enrollment control.platform_recovery_enrollment; old_envelope control.authority_envelope; new_envelope control.authority_envelope;
 lineage_ids uuid[]; original_floor timestamptz; proof_count integer; proofs jsonb[]; proof_deadline timestamptz;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF jsonb_typeof(n.resume_request) IS DISTINCT FROM 'object'
  OR jsonb_typeof(n.resume_request->'discoveryReceivingProof') IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF n.resume_request->'discoveryReceivingProof' IS DISTINCT FROM jsonb_build_object(
    'mfaChallengeId',n.resume_request#>'{discoveryReceivingProof,mfaChallengeId}',
    'verificationOperationId',n.resume_request#>'{discoveryReceivingProof,verificationOperationId}',
    'evidenceDigest',n.resume_request#>'{discoveryReceivingProof,evidenceDigest}')
  OR jsonb_typeof(n.resume_request#>'{discoveryReceivingProof,mfaChallengeId}') IS DISTINCT FROM 'string'
  OR jsonb_typeof(n.resume_request#>'{discoveryReceivingProof,verificationOperationId}') IS DISTINCT FROM 'string'
  OR jsonb_typeof(n.resume_request#>'{discoveryReceivingProof,evidenceDigest}') IS DISTINCT FROM 'string'
  OR (n.resume_request#>>'{discoveryReceivingProof,mfaChallengeId}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR (n.resume_request#>>'{discoveryReceivingProof,verificationOperationId}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR (n.resume_request#>>'{discoveryReceivingProof,evidenceDigest}') !~ '^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT old_attempt FROM control.mutation_candidate
  WHERE mutation_candidate_id=n.predecessor_candidate_id FOR UPDATE;
 SELECT * INTO STRICT old_envelope FROM control.authority_envelope
  WHERE participant_id=old_attempt.participant_id AND authority_envelope_id=old_attempt.maker_authority_envelope_id;
 SELECT * INTO STRICT previous FROM control.platform_recovery_case
  WHERE participant_id=old_attempt.participant_id AND privacy_domain_id=old_attempt.privacy_domain_id
   AND recovery_id=old_envelope.recovery_case_id;
 SELECT c.* INTO STRICT fresh FROM control.platform_recovery_case c JOIN control.authority_envelope e
  ON e.participant_id=c.participant_id AND e.recovery_case_id=c.recovery_id
  WHERE e.participant_id=n.participant_id AND c.privacy_domain_id=n.privacy_domain_id
   AND e.authority_envelope_id=n.maker_authority_envelope_id AND e.principal_id=n.maker_principal_id
   AND e.representation='RECOVERY_V1' AND e.authority_epoch=n.maker_authority_epoch
   AND e.delegation_epoch=n.maker_delegation_epoch AND openpc.platform_recovery_envelope_current(e.authority_envelope_id);
 SELECT * INTO STRICT new_envelope FROM control.authority_envelope WHERE participant_id=n.participant_id AND authority_envelope_id=n.maker_authority_envelope_id;
 SELECT * INTO STRICT old_enrollment FROM control.platform_recovery_enrollment WHERE enrollment_id=previous.enrollment_id;
 SELECT * INTO STRICT new_enrollment FROM control.platform_recovery_enrollment WHERE enrollment_id=fresh.enrollment_id;
 WITH RECURSIVE lineage AS (
  SELECT c.*,ARRAY[c.mutation_candidate_id] path FROM control.mutation_candidate c WHERE c.mutation_candidate_id=old_attempt.mutation_candidate_id
  UNION ALL SELECT parent.*,child.path||parent.mutation_candidate_id FROM lineage child
   JOIN control.mutation_candidate parent ON parent.mutation_candidate_id=child.predecessor_candidate_id
   WHERE NOT parent.mutation_candidate_id=any(child.path)
 ) SELECT array_agg(mutation_candidate_id),min(created_at) INTO lineage_ids,original_floor FROM lineage;
 IF lineage_ids IS NULL OR NOT EXISTS(SELECT 1 FROM control.mutation_candidate c WHERE c.mutation_candidate_id=any(lineage_ids)
    AND c.predecessor_candidate_id IS NULL AND c.attempt=1)
  OR EXISTS(SELECT 1 FROM control.mutation_candidate c WHERE c.mutation_candidate_id=any(lineage_ids)
    AND (row(c.participant_id,c.privacy_domain_id,c.action_intent_id,c.catalog_operation_id,c.resource_id,
      c.candidate_digest,c.candidate_document,c.expected_revision,c.idempotency_key,c.maker_principal_id)
      IS DISTINCT FROM row(n.participant_id,n.privacy_domain_id,n.action_intent_id,n.catalog_operation_id,n.resource_id,
        n.candidate_digest,n.candidate_document,n.expected_revision,n.idempotency_key,n.maker_principal_id)
      OR c.resource_type<>n.resource_type OR c.operation_class<>n.operation_class
      OR c.state NOT IN ('PROPOSED','APPROVAL_REQUESTED','APPROVED') OR c.consumed_operation_id IS NOT NULL
      OR (c.predecessor_candidate_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM control.mutation_candidate parent
        WHERE parent.mutation_candidate_id=c.predecessor_candidate_id AND parent.mutation_candidate_id=any(lineage_ids) AND parent.attempt=c.attempt-1))
      OR (c.predecessor_candidate_id IS NULL AND c.attempt<>1)))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT count(*),array_agg(jsonb_build_object('mfaChallengeId',m.mfa_challenge_id::text,
   'verificationOperationId',verification.operation_id::text,'evidenceDigest','sha256:'||encode(verification.evidence_digest,'hex'))),
   min(least(m.expires_at,
     case when proof_session.step_up_mfa_challenge_id is null then m.consumed_at+interval '5 minutes'
       else coalesce(openpc.session_step_up_valid_until(m.participant_id,m.session_id,m.principal_id),'-infinity'::timestamptz) end,
     coalesce(credential.valid_until,'infinity'::timestamptz)))
  INTO proof_count,proofs,proof_deadline FROM control.mfa_challenge m
 JOIN control.session proof_session ON proof_session.participant_id=m.participant_id
  AND proof_session.session_id=m.session_id AND proof_session.principal_id=m.principal_id
 JOIN control.credential credential ON credential.participant_id=m.participant_id AND credential.credential_id=m.signer_credential_id
  AND credential.principal_id=m.principal_id AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE'
  AND credential.credential_epoch=m.signer_credential_epoch AND credential.valid_from<=clock_timestamp()
  AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  AND sha256(credential.public_key_spki_der)=credential.public_key_digest
 JOIN control.mutation_evidence verification ON verification.participant_id=m.participant_id
  AND verification.mfa_challenge_id=m.mfa_challenge_id AND verification.privacy_domain_id=n.privacy_domain_id
  AND verification.principal_id=n.maker_principal_id AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
  AND verification.action_intent_id='ACT-IDENTITY_UPDATE_STEP_UP-V1'
  AND verification.aggregate_type='webauthn-verification' AND verification.aggregate_id=n.maker_session_id
  AND verification.signer_credential_id=m.signer_credential_id AND verification.webauthn_assertion_binding_digest IS NOT NULL
  AND verification.evidence_digest=sha256(verification.evidence_cbor) AND verification.occurred_at>=greatest(fresh.activated_at,new_envelope.valid_from)
  AND verification.occurred_at>=m.consumed_at AND verification.occurred_at<=clock_timestamp()
  AND verification.bound_participant_epoch=n.maker_participant_epoch AND verification.bound_principal_epoch=n.maker_principal_epoch
  AND verification.bound_authority_envelope_id=n.maker_authority_envelope_id AND verification.bound_envelope_epoch=n.maker_authority_epoch
  AND verification.bound_assignment_id=n.maker_assignment_id
 JOIN control.idempotency_record committed ON committed.participant_id=verification.participant_id
  AND committed.privacy_domain_id=verification.privacy_domain_id AND committed.operation_id=verification.operation_id
  AND committed.principal_id=verification.principal_id AND committed.action_intent_id=verification.action_intent_id
  AND committed.catalog_operation_id=verification.catalog_operation_id
  AND committed.input_digest=verification.candidate_digest AND committed.terminal_state='COMMITTED'
  AND committed.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
 JOIN control.outbox_event event ON event.participant_id=verification.participant_id AND event.privacy_domain_id=verification.privacy_domain_id
  AND event.aggregate_type=verification.aggregate_type AND event.aggregate_id=verification.aggregate_id
  AND event.event_type='openpc.identity.webauthn-verification.mutation.committed.v1'
  AND event.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
  AND event.payload_cbor=verification.evidence_cbor AND event.payload_digest=verification.evidence_digest AND event.cose_sign1=verification.cose_sign1
 WHERE m.participant_id=n.participant_id AND m.principal_id=n.maker_principal_id AND m.session_id=n.maker_session_id
  AND m.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1' AND m.resource_digest=sha256(convert_to(openpc.signing_canonical_json(n.resume_request-'discoveryReceivingProof'),'UTF8')) AND m.resource_id=n.predecessor_approval_id::text
  AND m.created_at>=greatest(fresh.activated_at,new_envelope.valid_from) AND m.consumed_at>=greatest(fresh.activated_at,new_envelope.valid_from)
  AND (CASE WHEN proof_session.step_up_mfa_challenge_id IS NULL
    THEN m.consumed_at>clock_timestamp()-interval '5 minutes'
    ELSE proof_session.step_up_mfa_challenge_id=m.mfa_challenge_id
      AND openpc.session_step_up_valid_until(m.participant_id,m.session_id,m.principal_id)>clock_timestamp() END)
  AND m.consumed_at<=clock_timestamp()
  AND m.expires_at>clock_timestamp() AND ((m.used_at IS NULL AND m.used_operation_id IS NULL) OR (m.used_at IS NOT NULL AND m.used_operation_id=n.resume_operation_id));
 IF proof_count<>1 OR n.resume_request->'discoveryReceivingProof' IS DISTINCT FROM proofs[1] THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF current_setting('transaction_isolation')<>'serializable'
  OR current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR old_enrollment.document->>'assurance' IS DISTINCT FROM 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'
  OR old_enrollment.document_digest<>previous.enrollment_digest OR old_enrollment.row_version<>previous.enrollment_revision
  OR new_enrollment.document_digest<>fresh.enrollment_digest OR new_enrollment.row_version<>fresh.enrollment_revision
  OR new_enrollment.document->>'assurance' IS DISTINCT FROM 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'
  OR old_attempt.catalog_operation_id<>'ID-OP-WORKLOAD-ROTATE'
  OR old_attempt.action_intent_id<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR old_attempt.resource_type<>'participant' OR old_attempt.operation_class<>'UPDATE'
  OR old_attempt.state NOT IN ('APPROVAL_REQUESTED','APPROVED') OR old_attempt.consumed_operation_id IS NOT NULL
  OR n.state NOT IN ('PROPOSED','APPROVAL_REQUESTED') OR n.consumed_operation_id IS NOT NULL
  OR n.predecessor_approval_id IS NULL OR n.resume_operation_id IS NULL
  OR fresh.intent->>'schemaVersion' IS DISTINCT FROM '2'
  OR n.attempt<>old_attempt.attempt+1 OR n.expires_at<=clock_timestamp()
  OR n.expires_at>least(clock_timestamp()+interval '30 minutes',fresh.valid_until,new_envelope.valid_until,
    (SELECT least(s.idle_expires_at,s.absolute_expires_at) FROM control.session s WHERE s.participant_id=n.participant_id AND s.session_id=n.maker_session_id),
    (SELECT upper(a.valid_during) FROM control.assignment a WHERE a.participant_id=n.participant_id AND a.assignment_id=n.maker_assignment_id))
  OR row(n.participant_id,n.privacy_domain_id,n.action_intent_id,n.catalog_operation_id,n.resource_type,
    n.operation_class,n.resource_id,n.candidate_digest,n.candidate_document,n.expected_revision,n.idempotency_key,n.maker_principal_id)
   IS DISTINCT FROM row(old_attempt.participant_id,old_attempt.privacy_domain_id,old_attempt.action_intent_id,
    old_attempt.catalog_operation_id,old_attempt.resource_type,old_attempt.operation_class,old_attempt.resource_id,
    old_attempt.candidate_digest,old_attempt.candidate_document,old_attempt.expected_revision,old_attempt.idempotency_key,old_attempt.maker_principal_id)
  OR old_envelope.representation<>'RECOVERY_V1' OR old_envelope.principal_id<>n.maker_principal_id
  OR old_enrollment.source_purpose<>'ROOT_EXPIRY_RECOVERY' OR new_enrollment.source_purpose<>'ROOT_EXPIRY_RECOVERY'
  OR old_enrollment.document->>'schemaVersion'<>'2' OR new_enrollment.document->>'schemaVersion'<>'2'
  OR previous.state<>'EXPIRED' OR previous.valid_until>clock_timestamp() OR previous.completion_operation_id IS NOT NULL OR previous.completion_result IS NOT NULL
  OR fresh.state<>'ACTIVE' OR fresh.recovery_id=previous.recovery_id OR fresh.valid_until<=clock_timestamp()
  OR previous.intent->>'schema' IS DISTINCT FROM 'pc.identity.discovery-certificate-recovery-intent'
  OR fresh.intent->>'schema' IS DISTINCT FROM previous.intent->>'schema'
  OR fresh.intent->'certificateRecovery' IS DISTINCT FROM previous.intent->'certificateRecovery'
  OR ((fresh.intent#>'{administrators,0}')-'principalEpoch') IS DISTINCT FROM ((previous.intent#>'{administrators,0}')-'principalEpoch')
  OR ((fresh.intent#>'{administrators,1}')-'principalEpoch') IS DISTINCT FROM ((previous.intent#>'{administrators,1}')-'principalEpoch')
  OR fresh.intent#>>'{administrators,0,principalId}' IS DISTINCT FROM n.maker_principal_id::text
  OR openpc.discovery_approval_resume_enrollments_compatible(old_enrollment.enrollment_id,new_enrollment.enrollment_id) IS DISTINCT FROM true
  OR n.resume_request IS DISTINCT FROM (SELECT jsonb_build_object('command','RESUME',
    'actionIntentId','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','actionIntentDigest','sha256:'||encode(action.semantic_digest,'hex'),
    'approvalRequestId','urn:openpc:resource:'||prior.approval_request_id::text,'expectedRevision',prior.row_version::text,
    'predecessorCandidateId',old_attempt.mutation_candidate_id::text,'expectedAttempt',old_attempt.attempt::text,
    'candidateDigest','sha256:'||encode(old_attempt.candidate_digest,'hex'),
    'reason','Resume the retained Discovery certificate rotation with fresh custody and independent approval.',
    'discoveryReceivingProof',proofs[1]) FROM control.approval_request prior JOIN control.action_intent action
      ON action.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
    WHERE prior.participant_id=n.participant_id AND prior.privacy_domain_id=n.privacy_domain_id
     AND prior.approval_request_id=n.predecessor_approval_id AND prior.subject_type='CONFIGURATION_CANDIDATE'
     AND prior.subject_id=old_attempt.mutation_candidate_id AND prior.subject_digest=n.candidate_digest
     AND prior.subject_version=n.expected_revision AND prior.action_intent_id=n.action_intent_id
     AND prior.maker_principal_id=n.maker_principal_id AND prior.checker_principal_id<>n.maker_principal_id
     AND prior.checker_principal_id::text=fresh.intent#>>'{administrators,1,principalId}'
     AND prior.state IN ('OPEN','APPROVED','EXPIRED'))
  OR n.candidate_document IS DISTINCT FROM jsonb_build_object('replacedCredentialId',fresh.intent#>>'{certificateRecovery,predecessorCredentialId}',
    'credentialId',fresh.intent#>>'{certificateRecovery,successorCredentialId}',
    'publicKeySpkiDer',fresh.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
  OR n.expected_revision::text IS DISTINCT FROM fresh.intent#>>'{certificateRecovery,predecessorRevision}'
  OR n.resource_id::text IS DISTINCT FROM fresh.intent#>>'{certificateRecovery,predecessorCredentialId}'
  OR n.candidate_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(n.candidate_document),'UTF8'))
  OR EXISTS(SELECT 1 FROM control.mutation_candidate child WHERE child.predecessor_candidate_id=old_attempt.mutation_candidate_id
    AND child.mutation_candidate_id<>n.mutation_candidate_id)
  OR NOT EXISTS(SELECT 1 FROM control.participant p JOIN control.principal principal ON principal.participant_id=p.participant_id
    JOIN control.session s ON s.participant_id=p.participant_id AND s.principal_id=principal.principal_id
    JOIN control.assignment a ON a.participant_id=p.participant_id AND a.principal_id=principal.principal_id
    WHERE p.participant_id=n.participant_id AND p.state='ACTIVE' AND p.authority_epoch=n.maker_participant_epoch
     AND principal.principal_id=n.maker_principal_id AND principal.state='ACTIVE' AND principal.kind='PLATFORM_OPERATOR'
     AND principal.authority_epoch=n.maker_principal_epoch AND s.session_id=n.maker_session_id AND s.state='ACTIVE'
     AND s.session_epoch=n.maker_session_epoch AND s.participant_epoch=n.maker_participant_epoch
     AND s.authority_epoch=n.maker_principal_epoch AND s.delegation_epoch=n.maker_delegation_epoch
     AND s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL
     AND s.idle_expires_at>clock_timestamp() AND s.absolute_expires_at>clock_timestamp()
     AND a.assignment_id=n.maker_assignment_id AND a.row_version=n.maker_assignment_row_version
     AND a.authority_envelope_id=n.maker_authority_envelope_id AND a.state='ACTIVE' AND a.valid_during @> clock_timestamp()
     AND a.delegation_epoch=n.maker_delegation_epoch AND a.maker_checker_required
     AND n.action_intent_id=any(a.action_intent_ids) AND n.privacy_domain_id::text=any(a.privacy_domain_ids)
     AND (n.resource_id::text=any(a.resource_ids) OR '*'=any(a.resource_ids)))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(fresh.enrollment_id,fresh.recovery_id);
 -- No state/time/currentness filter may hide a prior provider claim or effect.
 IF EXISTS(SELECT 1 FROM control.mfa_challenge m WHERE m.participant_id=n.participant_id
    AND m.principal_id=n.maker_principal_id AND m.action_intent_id=n.action_intent_id AND m.resource_digest=n.candidate_digest
    AND (m.used_at IS NOT NULL OR m.used_operation_id IS NOT NULL)
    AND NOT EXISTS(SELECT 1 FROM control.idempotency_record history WHERE history.participant_id=m.participant_id
      AND history.operation_id=m.used_operation_id AND history.terminal_state='COMMITTED'
      AND history.action_intent_id IN ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'))
    AND m.session_id IN(SELECT c.maker_session_id FROM control.mutation_candidate c WHERE c.mutation_candidate_id=any(lineage_ids)))
  OR EXISTS(SELECT 1 FROM control.discovery_certificate_issuance i WHERE i.participant_id=n.participant_id
    AND (i.predecessor_credential_id=n.resource_id OR i.successor_credential_id::text=n.candidate_document->>'credentialId'))
  OR EXISTS(SELECT 1 FROM control.discovery_certificate_issuer_attempt a WHERE a.participant_id=n.participant_id
    AND a.privacy_domain_id=n.privacy_domain_id AND a.idempotency_key=n.idempotency_key)
  OR EXISTS(SELECT 1 FROM control.idempotency_record r WHERE r.participant_id=n.participant_id AND r.privacy_domain_id=n.privacy_domain_id
    AND (r.idempotency_key=n.idempotency_key
     OR (r.input_digest=n.candidate_digest AND r.catalog_operation_id='ID-OP-WORKLOAD-ROTATE')))
  OR EXISTS(SELECT 1 FROM control.mutation_evidence e WHERE e.participant_id=n.participant_id AND e.privacy_domain_id=n.privacy_domain_id
    AND (e.candidate_digest=n.candidate_digest OR e.aggregate_id::text=n.candidate_document->>'credentialId'))
  OR EXISTS(SELECT 1 FROM control.audit_occurrence a WHERE a.participant_id=n.participant_id AND a.privacy_domain_id=n.privacy_domain_id
    AND (a.candidate_digest=n.candidate_digest OR a.aggregate_id::text=n.candidate_document->>'credentialId'))
  OR EXISTS(SELECT 1 FROM control.outbox_event e WHERE e.participant_id=n.participant_id AND e.privacy_domain_id=n.privacy_domain_id
    AND (e.aggregate_id::text=n.candidate_document->>'credentialId'
      OR (e.aggregate_id=n.resource_id AND e.created_at>=original_floor)))
  OR EXISTS(SELECT 1 FROM control.receipt_signing_attempt a JOIN control.business_transition_profile profile USING(profile_digest)
    WHERE a.participant_id=n.participant_id AND a.privacy_domain_id=n.privacy_domain_id
     AND profile.catalog_operation_id=n.catalog_operation_id AND a.reserved_at_ns>=extract(epoch from original_floor)*1000000000
     AND NOT EXISTS(SELECT 1 FROM control.idempotency_record committed WHERE committed.participant_id=a.participant_id
       AND committed.privacy_domain_id=a.privacy_domain_id AND committed.operation_id=a.operation_id AND committed.terminal_state='COMMITTED'))
  OR EXISTS(SELECT 1 FROM control.mutation_candidate c WHERE c.participant_id=n.participant_id AND c.privacy_domain_id=n.privacy_domain_id
    AND c.candidate_digest=n.candidate_digest AND (c.state NOT IN ('PROPOSED','APPROVAL_REQUESTED','APPROVED') OR c.consumed_operation_id IS NOT NULL OR (c.mutation_candidate_id<>n.mutation_candidate_id AND NOT c.mutation_candidate_id=any(lineage_ids))))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- Reselect the SAME strict native proof after every local absence scan. The
 -- final invoker trigger repeats this after the private cross-privacy scan and
 -- again at deferred success; crypto never becomes a writable verified flag.
 SELECT count(*),array_agg(jsonb_build_object('mfaChallengeId',m.mfa_challenge_id::text,
   'verificationOperationId',verification.operation_id::text,'evidenceDigest','sha256:'||encode(verification.evidence_digest,'hex'))),
   min(least(m.expires_at,
     case when proof_session.step_up_mfa_challenge_id is null then m.consumed_at+interval '5 minutes'
       else coalesce(openpc.session_step_up_valid_until(m.participant_id,m.session_id,m.principal_id),'-infinity'::timestamptz) end,
     coalesce(credential.valid_until,'infinity'::timestamptz)))
  INTO proof_count,proofs,proof_deadline FROM control.mfa_challenge m
 JOIN control.session proof_session ON proof_session.participant_id=m.participant_id
  AND proof_session.session_id=m.session_id AND proof_session.principal_id=m.principal_id
 JOIN control.credential credential ON credential.participant_id=m.participant_id AND credential.credential_id=m.signer_credential_id
  AND credential.principal_id=m.principal_id AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE'
  AND credential.credential_epoch=m.signer_credential_epoch AND credential.valid_from<=clock_timestamp()
  AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  AND sha256(credential.public_key_spki_der)=credential.public_key_digest
 JOIN control.mutation_evidence verification ON verification.participant_id=m.participant_id
  AND verification.mfa_challenge_id=m.mfa_challenge_id AND verification.privacy_domain_id=n.privacy_domain_id
  AND verification.principal_id=n.maker_principal_id AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
  AND verification.action_intent_id='ACT-IDENTITY_UPDATE_STEP_UP-V1'
  AND verification.aggregate_type='webauthn-verification' AND verification.aggregate_id=n.maker_session_id
  AND verification.signer_credential_id=m.signer_credential_id AND verification.webauthn_assertion_binding_digest IS NOT NULL
  AND verification.evidence_digest=sha256(verification.evidence_cbor) AND verification.occurred_at>=greatest(fresh.activated_at,new_envelope.valid_from)
  AND verification.occurred_at>=m.consumed_at AND verification.occurred_at<=clock_timestamp()
  AND verification.bound_participant_epoch=n.maker_participant_epoch AND verification.bound_principal_epoch=n.maker_principal_epoch
  AND verification.bound_authority_envelope_id=n.maker_authority_envelope_id AND verification.bound_envelope_epoch=n.maker_authority_epoch
  AND verification.bound_assignment_id=n.maker_assignment_id
 JOIN control.idempotency_record committed ON committed.participant_id=verification.participant_id
  AND committed.privacy_domain_id=verification.privacy_domain_id AND committed.operation_id=verification.operation_id
  AND committed.principal_id=verification.principal_id AND committed.action_intent_id=verification.action_intent_id
  AND committed.catalog_operation_id=verification.catalog_operation_id
  AND committed.input_digest=verification.candidate_digest AND committed.terminal_state='COMMITTED'
  AND committed.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
 JOIN control.outbox_event event ON event.participant_id=verification.participant_id AND event.privacy_domain_id=verification.privacy_domain_id
  AND event.aggregate_type=verification.aggregate_type AND event.aggregate_id=verification.aggregate_id
  AND event.event_type='openpc.identity.webauthn-verification.mutation.committed.v1'
  AND event.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
  AND event.payload_cbor=verification.evidence_cbor AND event.payload_digest=verification.evidence_digest AND event.cose_sign1=verification.cose_sign1
 WHERE m.participant_id=n.participant_id AND m.principal_id=n.maker_principal_id AND m.session_id=n.maker_session_id
  AND m.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1' AND m.resource_digest=sha256(convert_to(openpc.signing_canonical_json(n.resume_request-'discoveryReceivingProof'),'UTF8')) AND m.resource_id=n.predecessor_approval_id::text
  AND m.created_at>=greatest(fresh.activated_at,new_envelope.valid_from) AND m.consumed_at>=greatest(fresh.activated_at,new_envelope.valid_from)
  AND (CASE WHEN proof_session.step_up_mfa_challenge_id IS NULL
    THEN m.consumed_at>clock_timestamp()-interval '5 minutes'
    ELSE proof_session.step_up_mfa_challenge_id=m.mfa_challenge_id
      AND openpc.session_step_up_valid_until(m.participant_id,m.session_id,m.principal_id)>clock_timestamp() END)
  AND m.consumed_at<=clock_timestamp()
  AND m.expires_at>clock_timestamp() AND ((m.used_at IS NULL AND m.used_operation_id IS NULL) OR (m.used_at IS NOT NULL AND m.used_operation_id=n.resume_operation_id));
 IF proof_count<>1 OR n.resume_request->'discoveryReceivingProof' IS DISTINCT FROM proofs[1] THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- Run again at the actual end boundary, including after the private claim scan.
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(fresh.enrollment_id,fresh.recovery_id);
 IF NOT openpc.platform_recovery_envelope_current(n.maker_authority_envelope_id)
  OR NOT EXISTS(SELECT 1 FROM control.idempotency_record resume WHERE resume.participant_id=n.participant_id
    AND resume.privacy_domain_id=n.privacy_domain_id AND resume.operation_id=n.resume_operation_id
    AND resume.principal_id=n.maker_principal_id AND resume.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
    AND resume.catalog_operation_id='LEGACY' AND resume.input_digest=sha256(convert_to(openpc.signing_canonical_json(n.resume_request-'discoveryReceivingProof'),'UTF8'))
    AND ((resume.terminal_state IS NULL AND EXISTS(SELECT 1 FROM control.mfa_challenge unused
      WHERE unused.mfa_challenge_id::text=proofs[1]->>'mfaChallengeId' AND unused.participant_id=n.participant_id
       AND unused.used_at IS NULL AND unused.used_operation_id IS NULL))
      OR (resume.terminal_state='COMMITTED' AND EXISTS(SELECT 1 FROM control.mfa_challenge used
       WHERE used.mfa_challenge_id::text=proofs[1]->>'mfaChallengeId' AND used.participant_id=n.participant_id
        AND used.used_at IS NOT NULL AND used.used_operation_id=n.resume_operation_id))))
  OR proof_deadline<=clock_timestamp() OR fresh.valid_until<=clock_timestamp() OR n.expires_at<=clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM control.session s WHERE s.participant_id=n.participant_id AND s.session_id=n.maker_session_id
    AND s.principal_id=n.maker_principal_id AND s.state='ACTIVE' AND s.authority_epoch=n.maker_principal_epoch
    AND s.session_epoch=n.maker_session_epoch AND s.participant_epoch=n.maker_participant_epoch
    AND s.delegation_epoch=n.maker_delegation_epoch AND s.idle_expires_at>clock_timestamp() AND s.absolute_expires_at>clock_timestamp())
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.assert_discovery_approval_resume(control.mutation_candidate) FROM PUBLIC;


DROP POLICY IF EXISTS discovery_approval_resume_stored_child_read ON control.mutation_candidate;
CREATE POLICY discovery_approval_resume_stored_child_read ON control.mutation_candidate FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)
  AND catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  AND resume_request->>'command'='RESUME' AND resume_request ? 'discoveryReceivingProof' AND predecessor_candidate_id IS NOT NULL
  AND state IN ('PROPOSED','APPROVAL_REQUESTED') AND consumed_operation_id IS NULL AND EXISTS(
   SELECT 1 FROM control.platform_recovery_case c JOIN control.platform_recovery_enrollment e
    ON e.enrollment_id=c.enrollment_id AND e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
   WHERE c.participant_id=mutation_candidate.participant_id AND c.privacy_domain_id=mutation_candidate.privacy_domain_id
    AND c.recovery_id=(SELECT e2.recovery_case_id FROM control.authority_envelope e2 WHERE e2.participant_id=mutation_candidate.participant_id AND e2.authority_envelope_id=mutation_candidate.maker_authority_envelope_id AND e2.principal_id=mutation_candidate.maker_principal_id AND e2.representation='RECOVERY_V1')
    AND c.state='ACTIVE' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
    AND e.state='ACTIVE' AND e.row_version=c.enrollment_revision AND e.document_digest=c.enrollment_digest
    AND c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
    AND e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' AND current_setting('openpc.local_qa_runtime',true)='1'
    AND c.intent->'certificateRecovery'=e.document->'certificateRecovery'
    AND mutation_candidate.resource_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
    AND mutation_candidate.candidate_document=jsonb_build_object('replacedCredentialId',mutation_candidate.resource_id::text,
      'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
      'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')));
CREATE OR REPLACE FUNCTION openpc.guard_discovery_approval_resume_target_claims()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE c control.platform_recovery_case; stored control.mutation_candidate;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'mutation_candidate' OR TG_OP<>'INSERT'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.catalog_operation_id<>'ID-OP-WORKLOAD-ROTATE' OR NEW.resume_request->>'command' IS DISTINCT FROM 'RESUME' THEN RETURN NEW; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
 IF (to_jsonb(stored)-ARRAY['state','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','updated_at']) OR stored.state NOT IN ('PROPOSED','APPROVAL_REQUESTED') OR stored.consumed_operation_id IS NOT NULL THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT c FROM control.platform_recovery_case
  WHERE recovery_id=(SELECT e.recovery_case_id FROM control.authority_envelope e WHERE e.participant_id=NEW.participant_id AND e.authority_envelope_id=NEW.maker_authority_envelope_id AND e.principal_id=NEW.maker_principal_id AND e.representation='RECOVERY_V1') AND participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)
   AND state='ACTIVE' AND valid_from<=clock_timestamp() AND valid_until>clock_timestamp()
   AND intent->>'schema'='pc.identity.discovery-certificate-recovery-intent' AND intent->>'schemaVersion'='2';
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NEW.catalog_operation_id<>'ID-OP-WORKLOAD-ROTATE' OR NEW.action_intent_id<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.resource_id::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorCredentialId}'
  OR NEW.candidate_document IS DISTINCT FROM jsonb_build_object('replacedCredentialId',NEW.resource_id::text,
    'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
    'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
  OR NEW.expected_revision::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorRevision}'
  OR NEW.maker_principal_id::text IS DISTINCT FROM c.intent#>>'{administrators,0,principalId}'
  OR NEW.state NOT IN ('PROPOSED','APPROVAL_REQUESTED') OR NEW.consumed_operation_id IS NOT NULL OR NEW.predecessor_candidate_id IS NULL
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF EXISTS(SELECT 1 FROM control.discovery_certificate_issuance i WHERE i.participant_id=c.participant_id
    AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
     OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
  OR EXISTS(SELECT 1 FROM control.discovery_certificate_issuer_attempt a JOIN control.discovery_certificate_issuance i
    ON i.participant_id=a.participant_id AND i.issuance_id=a.issuance_id WHERE i.participant_id=c.participant_id
     AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
      OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- A clock advance may have hidden all target rows through their RLS basis.
 -- Reauthenticate the SAME case/source after the scan before any success.
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_case fresh WHERE fresh.recovery_id=c.recovery_id
   AND fresh.participant_id=c.participant_id AND fresh.privacy_domain_id=c.privacy_domain_id AND fresh.state='ACTIVE'
   AND fresh.enrollment_id=c.enrollment_id AND fresh.enrollment_revision=c.enrollment_revision
   AND fresh.enrollment_digest=c.enrollment_digest AND fresh.intent=c.intent
   AND fresh.valid_from<=clock_timestamp() AND fresh.valid_until>clock_timestamp())
  OR NEW.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_discovery_approval_resume_target_claims() FROM PUBLIC;
DROP TRIGGER IF EXISTS zz_discovery_approval_resume_claims ON control.mutation_candidate;
CREATE TRIGGER zz_discovery_approval_resume_claims AFTER INSERT ON control.mutation_candidate
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_approval_resume_target_claims();
DROP TRIGGER IF EXISTS zz_discovery_approval_resume_claims_completed ON control.mutation_candidate;
CREATE CONSTRAINT TRIGGER zz_discovery_approval_resume_claims_completed AFTER INSERT ON control.mutation_candidate
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_approval_resume_target_claims();

CREATE OR REPLACE FUNCTION openpc.guard_discovery_approval_resume_final()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE stored control.mutation_candidate;
BEGIN
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND NEW.resume_request->>'command'='RESUME' THEN
  SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
  IF (to_jsonb(stored)-ARRAY['state','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','updated_at'])
   OR stored.state NOT IN ('PROPOSED','APPROVAL_REQUESTED') OR stored.consumed_operation_id IS NOT NULL
  THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
  PERFORM openpc.assert_discovery_approval_resume(stored);
 END IF;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_discovery_approval_resume_final() FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.guard_discovery_approval_resume_completed()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE stored control.mutation_candidate;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'mutation_candidate' OR TG_OP<>'INSERT'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND NEW.resume_request->>'command'='RESUME' THEN
  SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
  IF (to_jsonb(stored)-ARRAY['state','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','updated_at'])
   OR stored.state IS DISTINCT FROM 'APPROVAL_REQUESTED' OR stored.consumed_operation_id IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM control.idempotency_record resume JOIN control.approval_request approval
    ON approval.participant_id=resume.participant_id AND approval.privacy_domain_id=resume.privacy_domain_id
     AND approval.subject_type='CONFIGURATION_CANDIDATE' AND approval.subject_id=stored.mutation_candidate_id
    WHERE resume.participant_id=stored.participant_id AND resume.privacy_domain_id=stored.privacy_domain_id
     AND resume.operation_id=stored.resume_operation_id AND resume.terminal_state='COMMITTED'
     AND resume.expected_aggregate_version::text=stored.resume_request->>'expectedRevision'
     AND resume.principal_id=stored.maker_principal_id AND resume.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
     AND resume.catalog_operation_id='LEGACY' AND approval.state='OPEN' AND approval.row_version=1
     AND approval.subject_digest=stored.candidate_digest AND approval.subject_version=stored.expected_revision
     AND approval.action_intent_id=stored.action_intent_id AND approval.maker_principal_id=stored.maker_principal_id
     AND approval.checker_principal_id<>stored.maker_principal_id AND approval.expires_at=stored.expires_at
     AND resume.result_payload->>'resourceRef'='urn:openpc:resource:'||approval.approval_request_id::text)
  THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
  PERFORM openpc.assert_discovery_approval_resume(stored);
 END IF;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_discovery_approval_resume_completed() FROM PUBLIC;
DROP TRIGGER IF EXISTS zz_discovery_approval_resume_final ON control.mutation_candidate;
CREATE TRIGGER zz_discovery_approval_resume_final AFTER INSERT ON control.mutation_candidate
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_approval_resume_final();
DROP TRIGGER IF EXISTS zz_discovery_approval_resume_final_completed ON control.mutation_candidate;
CREATE CONSTRAINT TRIGGER zz_discovery_approval_resume_final_completed AFTER INSERT ON control.mutation_candidate
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_approval_resume_completed();


-- Only the private source owner can inspect cross-privacy claims for the exact
-- target of an actual active, installed local Discovery case. No rows are exposed.
DROP POLICY IF EXISTS discovery_preapproval_target_claim_read ON control.discovery_certificate_issuance;
CREATE POLICY discovery_preapproval_target_claim_read ON control.discovery_certificate_issuance FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND EXISTS(
  SELECT 1 FROM control.platform_recovery_case c JOIN control.platform_recovery_enrollment e
   ON e.enrollment_id=c.enrollment_id AND e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
  WHERE c.participant_id=discovery_certificate_issuance.participant_id AND openpc.matches_privacy(c.privacy_domain_id)
   AND c.state='ACTIVE' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
   AND e.state='ACTIVE' AND e.row_version=c.enrollment_revision AND e.document_digest=c.enrollment_digest
   AND c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   AND e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' AND current_setting('openpc.local_qa_runtime',true)='1'
   AND c.intent->'certificateRecovery'=e.document->'certificateRecovery'
   AND (discovery_certificate_issuance.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
     OR discovery_certificate_issuance.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}')));
DROP POLICY IF EXISTS discovery_preapproval_target_attempt_read ON control.discovery_certificate_issuer_attempt;
CREATE POLICY discovery_preapproval_target_attempt_read ON control.discovery_certificate_issuer_attempt FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND EXISTS(
  SELECT 1 FROM control.discovery_certificate_issuance i
   JOIN control.platform_recovery_case c ON c.participant_id=i.participant_id
   JOIN control.platform_recovery_enrollment e ON e.enrollment_id=c.enrollment_id AND e.participant_id=c.participant_id
    AND e.privacy_domain_id=c.privacy_domain_id
  WHERE i.participant_id=discovery_certificate_issuer_attempt.participant_id AND i.issuance_id=discovery_certificate_issuer_attempt.issuance_id
   AND openpc.matches_privacy(c.privacy_domain_id) AND c.state='ACTIVE'
   AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
   AND e.state='ACTIVE' AND e.row_version=c.enrollment_revision AND e.document_digest=c.enrollment_digest
   AND c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   AND e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' AND current_setting('openpc.local_qa_runtime',true)='1'
   AND c.intent->'certificateRecovery'=e.document->'certificateRecovery'
   AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
     OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}')));

-- The old callable case oracle is withdrawn. Only a real candidate INSERT's
-- private trigger can cross privacy boundaries, between the invoker admission
-- trigger and its invoker final-clock/proof recheck.
DROP FUNCTION IF EXISTS openpc.assert_discovery_preapproval_target_no_claim(uuid);
-- A stored child is visible only to this trigger owner for its exact installed,
-- current, local Discovery target. This policy never recurses into candidates.
DROP POLICY IF EXISTS discovery_preapproval_stored_child_read ON control.mutation_candidate;
CREATE POLICY discovery_preapproval_stored_child_read ON control.mutation_candidate FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)
  AND catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  AND resume_request->>'command'='DISCOVERY_PREAPPROVAL_CONTINUE' AND predecessor_candidate_id IS NOT NULL
  AND state='PROPOSED' AND consumed_operation_id IS NULL AND EXISTS(
   SELECT 1 FROM control.platform_recovery_case c JOIN control.platform_recovery_enrollment e
    ON e.enrollment_id=c.enrollment_id AND e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
   WHERE c.participant_id=mutation_candidate.participant_id AND c.privacy_domain_id=mutation_candidate.privacy_domain_id
    AND c.recovery_id::text=mutation_candidate.resume_request->>'recoveryId'
    AND c.state='ACTIVE' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
    AND e.state='ACTIVE' AND e.row_version=c.enrollment_revision AND e.document_digest=c.enrollment_digest
    AND c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
    AND e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' AND current_setting('openpc.local_qa_runtime',true)='1'
    AND c.intent->'certificateRecovery'=e.document->'certificateRecovery'
    AND mutation_candidate.resource_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
    AND mutation_candidate.candidate_document=jsonb_build_object('replacedCredentialId',mutation_candidate.resource_id::text,
      'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
      'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')));
CREATE OR REPLACE FUNCTION openpc.guard_discovery_preapproval_target_claims()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE c control.platform_recovery_case; stored control.mutation_candidate;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'mutation_candidate' OR TG_OP<>'INSERT'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.resume_request->>'command' IS DISTINCT FROM 'DISCOVERY_PREAPPROVAL_CONTINUE' THEN RETURN NEW; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id() IS DISTINCT FROM NEW.action_intent_id THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
 IF to_jsonb(stored) IS DISTINCT FROM to_jsonb(NEW) THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT c FROM control.platform_recovery_case
  WHERE recovery_id::text=NEW.resume_request->>'recoveryId' AND participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)
   AND state='ACTIVE' AND valid_from<=clock_timestamp() AND valid_until>clock_timestamp()
   AND intent->>'schema'='pc.identity.discovery-certificate-recovery-intent';
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NEW.catalog_operation_id<>'ID-OP-WORKLOAD-ROTATE' OR NEW.action_intent_id<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.resource_id::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorCredentialId}'
  OR NEW.candidate_document IS DISTINCT FROM jsonb_build_object('replacedCredentialId',NEW.resource_id::text,
    'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
    'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
  OR NEW.expected_revision::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorRevision}'
  OR NEW.maker_principal_id::text IS DISTINCT FROM c.intent#>>'{administrators,0,principalId}'
  OR NEW.state<>'PROPOSED' OR NEW.consumed_operation_id IS NOT NULL OR NEW.predecessor_candidate_id IS NULL
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF EXISTS(SELECT 1 FROM control.discovery_certificate_issuance i WHERE i.participant_id=c.participant_id
    AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
     OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
  OR EXISTS(SELECT 1 FROM control.discovery_certificate_issuer_attempt a JOIN control.discovery_certificate_issuance i
    ON i.participant_id=a.participant_id AND i.issuance_id=a.issuance_id WHERE i.participant_id=c.participant_id
     AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
      OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- A clock advance may have hidden all target rows through their RLS basis.
 -- Reauthenticate the SAME case/source after the scan before any success.
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_case fresh WHERE fresh.recovery_id=c.recovery_id
   AND fresh.participant_id=c.participant_id AND fresh.privacy_domain_id=c.privacy_domain_id AND fresh.state='ACTIVE'
   AND fresh.enrollment_id=c.enrollment_id AND fresh.enrollment_revision=c.enrollment_revision
   AND fresh.enrollment_digest=c.enrollment_digest AND fresh.intent=c.intent
   AND fresh.valid_from<=clock_timestamp() AND fresh.valid_until>clock_timestamp())
  OR NEW.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_discovery_preapproval_target_claims() FROM PUBLIC;
DROP TRIGGER IF EXISTS zz_discovery_preapproval_claims ON control.mutation_candidate;
CREATE TRIGGER zz_discovery_preapproval_claims AFTER INSERT ON control.mutation_candidate
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_preapproval_target_claims();
DROP TRIGGER IF EXISTS zz_discovery_preapproval_claims_completed ON control.mutation_candidate;
CREATE CONSTRAINT TRIGGER zz_discovery_preapproval_claims_completed AFTER INSERT ON control.mutation_candidate
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_preapproval_target_claims();

CREATE OR REPLACE FUNCTION openpc.guard_discovery_preapproval_final()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NEW.resume_request->>'command'='DISCOVERY_PREAPPROVAL_CONTINUE' THEN
  PERFORM openpc.assert_discovery_preapproval_continuation(NEW);
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_discovery_preapproval_final() FROM PUBLIC;
DROP TRIGGER IF EXISTS zz_discovery_preapproval_final ON control.mutation_candidate;
CREATE TRIGGER zz_discovery_preapproval_final AFTER INSERT ON control.mutation_candidate
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_preapproval_final();
DROP TRIGGER IF EXISTS zz_discovery_preapproval_final_completed ON control.mutation_candidate;
CREATE CONSTRAINT TRIGGER zz_discovery_preapproval_final_completed AFTER INSERT ON control.mutation_candidate
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_preapproval_final();

CREATE OR REPLACE FUNCTION openpc.platform_history_mfa_challenge_resume_read(p_row jsonb)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE r control.mfa_challenge;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.mfa_challenge,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 RETURN coalesce((case when (r."action_intent_id"='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1' and r."consumed_at" is not null) then (openpc.matches_participant(r."participant_id") and openpc.matches_privacy(openpc.current_privacy_domain_id())
      and exists(select 1 from control.platform_recovery_enrollment source
        where source.participant_id=r."participant_id" and source.privacy_domain_id=openpc.current_privacy_domain_id()
          and openpc.platform_recovery_continuation_root_matches(source.platform_context_id,source.participant_id,source.root_epoch,source.root_revision)
          and ((source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' and source.document->>'schemaVersion'='3')
            or (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='4'))
          and source.document->>'schema'='pc.identity.platform-recovery-enrollment' and source.state='ACTIVE' and source.row_version=1
          and source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
          and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
          and source.valid_from<=clock_timestamp() and source.valid_until>clock_timestamp()
          and openpc.current_action_intent_id() in ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1', 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1', 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1', 'ACT-IDENTITY_CREATE_SESSION-V1', 'ACT-IDENTITY_DELETE_SESSION-V1', 'ACT-IDENTITY_UPDATE_STEP_UP-V1', 'ACT-OPERATIONS_READ_OPERATION-V1', 'ACT-PARTICIPANTS_READ_RESOURCE-V1', 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1', 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1', 'ACT-PARTICIPANT_CREATE_MEMBER-V1', 'ACT-POLICY_APPROVE_REQUEST-V1', 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1', 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          and (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY'
      and source.document->>'schemaVersion'='4'
      and exists(select 1 from control.platform_recovery_case historical
        where historical.participant_id=source.participant_id
          and historical.privacy_domain_id=source.privacy_domain_id
          and historical.enrollment_id=source.enrollment_id
          and historical.enrollment_revision=source.row_version
          and historical.enrollment_digest=source.document_digest
          and historical.state='EXPIRED' and historical.valid_until<=clock_timestamp()
          and historical.intent->'pendingExpiry'=source.document#>'{source,pendingExpiry}'
          and (not (historical.intent ? 'approvalContinuation') or (
    historical.intent#>>'{approvalContinuation,schema}'='pc.identity.platform-prepare-approval-continuation'
    and historical.intent#>>'{approvalContinuation,schemaVersion}'='1'
    and historical.intent#>>'{approvalContinuation,recoveryId}'<>historical.recovery_id::text
    and historical.intent#>>'{approvalContinuation,recoveryId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,candidateId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,approvalId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,candidateDigest}'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(historical.intent->'preparation'),'UTF8')),'hex')
    and historical.intent#>>'{approvalContinuation,attempt}' ~ '^[1-9][0-9]{0,19}$'
  ))
          and historical.intent_digest=sha256(convert_to(openpc.signing_canonical_json(historical.intent),'UTF8'))
          and historical.activation_operation_id is not null
          and historical.activation_evidence_digest=sha256(historical.activation_evidence_cbor)
          and octet_length(historical.activation_cose)>0
          and (exists(select 1 from control.mutation_candidate resume_candidate
      where resume_candidate.participant_id=historical.participant_id
        and resume_candidate.privacy_domain_id=historical.privacy_domain_id
        and resume_candidate.catalog_operation_id='ID-OP-PLATFORM-SCOPE-PREPARE'
        and resume_candidate.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
        and resume_candidate.resource_type='participant' and resume_candidate.operation_class='UPDATE'
        and resume_candidate.expected_revision=0
        and resume_candidate.resource_id::text=historical.intent#>>'{preparation,replacementId}'
        and resume_candidate.candidate_document=historical.intent->'preparation'
        and resume_candidate.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(resume_candidate.candidate_document),'UTF8'))
        and resume_candidate.maker_principal_id::text=historical.intent#>>'{preparation,administrators,0,principalId}'
        and resume_candidate.predecessor_candidate_id::text=historical.intent#>>'{approvalContinuation,candidateId}'
        and resume_candidate.predecessor_approval_id::text=historical.intent#>>'{approvalContinuation,approvalId}'
        and resume_candidate.idempotency_key=historical.intent#>>'{approvalContinuation,businessKey}'
        and resume_candidate.attempt=(historical.intent#>>'{approvalContinuation,attempt}')::numeric+1
        and resume_candidate.state in ('PROPOSED','APPROVAL_REQUESTED','APPROVED')
        and resume_candidate.expires_at<=clock_timestamp() and resume_candidate.consumed_operation_id is null
        and resume_candidate.resume_operation_id is not null
        and resume_candidate.resume_request->>'command'='RESUME'
        and exists(select 1 from jsonb_array_elements(historical.lease_bindings) binding
          where binding->>'envelopeId'=resume_candidate.maker_authority_envelope_id::text
            and binding->>'assignmentId'=resume_candidate.maker_assignment_id::text
            and binding->>'principalId'=resume_candidate.maker_principal_id::text
            and binding->>'principalEpoch'=resume_candidate.maker_principal_epoch::text)
        and ( r."principal_id"=resume_candidate.maker_principal_id and r."session_id"=resume_candidate.maker_session_id
          and r."action_intent_id"='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
          and ((r."used_at" is null and r."used_operation_id" is null)
            or (r."used_operation_id"=resume_candidate.resume_operation_id and r."used_at" is not null))
          and r."resource_id"=resume_candidate.predecessor_approval_id::text
          and r."created_at">=historical.activated_at
          and r."consumed_at" is not null and r."consumed_at"<=resume_candidate.created_at
          and resume_candidate.created_at<r."expires_at"
          and r."resource_digest"=sha256(convert_to(openpc.signing_canonical_json(resume_candidate.resume_request),'UTF8'))))))))) else false end),false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $$;
REVOKE ALL ON FUNCTION openpc.platform_history_mfa_challenge_resume_read(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.platform_history_mfa_challenge_resume_read(jsonb) TO openpc_control_owner;

CREATE OR REPLACE FUNCTION openpc.platform_history_idempotency_record_resume_read(p_row jsonb)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE r control.idempotency_record;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.idempotency_record,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 RETURN coalesce((case when ((r."catalog_operation_id"='LEGACY' and r."action_intent_id"='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1') or (r."catalog_operation_id"='ID-OP-WEBAUTHN-VERIFY' and r."action_intent_id"='ACT-IDENTITY_UPDATE_STEP_UP-V1')) then (openpc.matches_participant(r."participant_id") and openpc.matches_privacy(r."privacy_domain_id")
      and exists(select 1 from control.platform_recovery_enrollment source
        where source.participant_id=r."participant_id" and source.privacy_domain_id=r."privacy_domain_id"
          and openpc.platform_recovery_continuation_root_matches(source.platform_context_id,source.participant_id,source.root_epoch,source.root_revision)
          and ((source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' and source.document->>'schemaVersion'='3')
            or (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='4'))
          and source.document->>'schema'='pc.identity.platform-recovery-enrollment' and source.state='ACTIVE' and source.row_version=1
          and source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
          and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
          and source.valid_from<=clock_timestamp() and source.valid_until>clock_timestamp()
          and openpc.current_action_intent_id() in ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1', 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1', 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1', 'ACT-IDENTITY_CREATE_SESSION-V1', 'ACT-IDENTITY_DELETE_SESSION-V1', 'ACT-IDENTITY_UPDATE_STEP_UP-V1', 'ACT-OPERATIONS_READ_OPERATION-V1', 'ACT-PARTICIPANTS_READ_RESOURCE-V1', 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1', 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1', 'ACT-PARTICIPANT_CREATE_MEMBER-V1', 'ACT-POLICY_APPROVE_REQUEST-V1', 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1', 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          and (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY'
      and source.document->>'schemaVersion'='4'
      and exists(select 1 from control.platform_recovery_case historical
        where historical.participant_id=source.participant_id
          and historical.privacy_domain_id=source.privacy_domain_id
          and historical.enrollment_id=source.enrollment_id
          and historical.enrollment_revision=source.row_version
          and historical.enrollment_digest=source.document_digest
          and historical.state='EXPIRED' and historical.valid_until<=clock_timestamp()
          and historical.intent->'pendingExpiry'=source.document#>'{source,pendingExpiry}'
          and (not (historical.intent ? 'approvalContinuation') or (
    historical.intent#>>'{approvalContinuation,schema}'='pc.identity.platform-prepare-approval-continuation'
    and historical.intent#>>'{approvalContinuation,schemaVersion}'='1'
    and historical.intent#>>'{approvalContinuation,recoveryId}'<>historical.recovery_id::text
    and historical.intent#>>'{approvalContinuation,recoveryId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,candidateId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,approvalId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
