ALTER DEFAULT PRIVILEGES FOR ROLE "openpc_control_owner" IN SCHEMA control REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

DO $function_grant_acceptance$
DECLARE expected record; matched oid;
BEGIN
 FOR expected IN SELECT * FROM (VALUES ('openpc.platform_scope_pending_record_digest(control.platform_scope_replacement)','openpc_control_owner'),
('openpc.platform_scope_pending_root_bridge_current(control.platform_scope_replacement,numeric,numeric,bytea)','openpc_control_owner'),
('openpc.platform_scope_pending_root_bridge_current(control.platform_scope_replacement,numeric,numeric,bytea)','openpc_control_runtime'),
('openpc.platform_scope_pending_root_bridge_current(control.platform_scope_replacement,numeric,numeric,bytea)','openpc_control_platform_runtime'),
('openpc.platform_history_mfa_challenge_resume_read(jsonb)','openpc_control_owner'),
('openpc.platform_history_idempotency_record_resume_read(jsonb)','openpc_control_owner'),
('openpc.platform_history_mutation_evidence_resume_read(jsonb)','openpc_control_owner'),
('openpc.platform_history_outbox_event_resume_read(jsonb)','openpc_control_owner'),
('openpc.platform_history_outbox_event_case_read(jsonb)','openpc_control_owner'),
('openpc.platform_recovery_continuation_root_matches(uuid,uuid,numeric,numeric)','openpc_control_owner'),
('openpc.platform_recovery_source_root_current(control.platform_recovery_enrollment)','openpc_control_owner'),
('openpc.platform_recovery_source_root_current(control.platform_recovery_enrollment)','openpc_control_runtime'),
